import type { BankQuestion } from "@/lib/bank";

/** Science and Technology (Space, Defence, IT) (General Knowledge): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "gk-science-tech-1", "question": "The headquarters of the Indian Space Research Organisation (ISRO) is in:", "options": ["Bengaluru", "Ahmedabad", "Sriharikota", "Thiruvananthapuram"], "answer": 0, "explanation": "ISRO is headquartered at Antariksh Bhavan, Bengaluru. Sriharikota is the launch centre and Thiruvananthapuram has VSSC.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-2", "question": "India’s first satellite, launched in 1975, was:", "options": ["Aryabhata", "Rohini", "Bhaskara", "INSAT-1A"], "answer": 0, "explanation": "Aryabhata, named after the ancient astronomer, was launched on 19 April 1975.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-3", "question": "Chandrayaan-3’s lander touched down near the Moon’s south pole on 23 August 2023. What is that date now observed as in India?", "options": ["National Astronomy Day", "National Technology Day", "National Space Day", "National Science Day"], "answer": 2, "explanation": "23 August is observed as National Space Day. National Science Day is 28 February and National Technology Day (Pokhran-II) is 11 May.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-4", "question": "DRDO stands for:", "options": ["Defence Research and Development Organisation", "Defence Research and Design Office", "Department of Research and Defence Operations", "Defence Resource and Deployment Office"], "answer": 0, "explanation": "DRDO, formed in 1958, is the R&D wing of the Ministry of Defence that developed the Agni, Prithvi and Akash missiles.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-5", "question": "India’s Mars Orbiter Mission (Mangalyaan), launched in November 2013, was carried by:", "options": ["PSLV", "LVM3", "GSLV Mk II", "SSLV"], "answer": 0, "explanation": "PSLV-C25 launched the Mars Orbiter Mission; it entered Mars orbit on 24 September 2014, making India the first country to succeed on its first attempt.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-6", "question": "Aditya-L1, India’s solar observatory launched in 2023, is placed:", "options": ["In orbit around the Moon", "In a halo orbit around the Sun–Earth Lagrange point L1", "In a geostationary orbit", "In a low Earth polar orbit"], "answer": 1, "explanation": "Aditya-L1 sits about 1.5 million km from Earth around L1, from where it can watch the Sun without being blocked by Earth or the Moon.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-7", "question": "BrahMos, a supersonic cruise missile, is a joint venture between India and:", "options": ["France", "Russia", "USA", "Israel"], "answer": 1, "explanation": "BrahMos Aerospace is an India–Russia joint venture; the name joins the Brahmaputra and Moskva rivers.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-8", "question": "The launch centre at Sriharikota is named after:", "options": ["Vikram Sarabhai", "A.P.J. Abdul Kalam", "Satish Dhawan", "Homi J. Bhabha"], "answer": 2, "explanation": "It is the Satish Dhawan Space Centre (SDSC SHAR). The Vikram Sarabhai Space Centre is at Thiruvananthapuram.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-9", "question": "India’s first nuclear test at Pokhran in May 1974 was code-named:", "options": ["Smiling Buddha", "Operation Shakti", "Operation Meghdoot", "Operation Vijay"], "answer": 0, "explanation": "The 1974 test was “Smiling Buddha”. The 1998 tests were Operation Shakti; Operation Vijay (1999) was the Kargil operation.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-10", "question": "Who is known as the father of the Indian space programme?", "options": ["Satish Dhawan", "Vikram Sarabhai", "U.R. Rao", "Homi J. Bhabha"], "answer": 1, "explanation": "Vikram Sarabhai founded INCOSPAR (1962), which became ISRO in 1969. Homi Bhabha is called the father of India’s nuclear programme.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-11", "question": "In cyber security, “phishing” means:", "options": ["Secretly recording keystrokes on a computer", "Encrypting a victim’s files and demanding payment", "Tricking people into revealing sensitive details by posing as a trustworthy source", "Flooding a server with traffic so that it crashes"], "answer": 2, "explanation": "Phishing uses fake emails, messages or websites to steal passwords and bank details. Flooding a server is a DoS attack and encrypting files for money is ransomware.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-12", "question": "Bt cotton is resistant to bollworm because it carries a gene from:", "options": ["Rhizobium", "Agrobacterium tumefaciens", "Escherichia coli", "Bacillus thuringiensis"], "answer": 3, "explanation": "The cry gene from the soil bacterium Bacillus thuringiensis makes a protein toxic to bollworm larvae. Agrobacterium is a vector used to insert genes.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-13", "question": "In June 2025, who became the first Indian astronaut to visit the International Space Station, on the Axiom-4 mission?", "options": ["Rakesh Sharma", "Ajit Krishnan", "Prasanth Balakrishnan Nair", "Shubhanshu Shukla"], "answer": 3, "explanation": "Group Captain Shubhanshu Shukla flew to the ISS on Axiom-4, launched on 25 June 2025. Rakesh Sharma flew to the Soviet Salyut-7 station in 1984; Nair and Krishnan are fellow Gaganyaan astronaut-designates.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-14", "question": "LVM3 (earlier GSLV Mk III), which launched Chandrayaan-3, uses which upper stage?", "options": ["L110 liquid stage", "S200 solid stage", "C25 cryogenic stage", "PS4 liquid stage"], "answer": 2, "explanation": "LVM3 has two S200 solid boosters, an L110 liquid core and the indigenous C25 cryogenic upper stage. PS4 is the fourth stage of the PSLV.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-15", "question": "“Mission Divyastra” (March 2024) was the first flight test of the Agni-V missile with:", "options": ["An anti-satellite warhead", "A hypersonic glide vehicle", "Multiple Independently targetable Re-entry Vehicle (MIRV) technology", "A submarine launch platform"], "answer": 2, "explanation": "Mission Divyastra tested Agni-V carrying MIRVs, which let one missile strike several targets. India’s anti-satellite test was Mission Shakti (2019).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-16", "question": "India’s nuclear doctrine, made public in 2003, is based on:", "options": ["Launch on warning", "Credible minimum deterrence and no first use", "First use against any conventional attack", "Nuclear sharing with allies"], "answer": 1, "explanation": "The doctrine commits India to no first use, building a credible minimum deterrent, with massive retaliation if attacked and no use against non-nuclear states.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-17", "question": "The third stage of India’s three-stage nuclear power programme aims to use:", "options": ["Enriched uranium in light water reactors", "Plutonium in fast breeder reactors only", "Natural uranium in pressurised heavy water reactors", "Thorium, through uranium-233 based reactors"], "answer": 3, "explanation": "Stage 1: natural uranium in PHWRs; stage 2: plutonium in fast breeder reactors; stage 3: thorium converted to U-233. India has large thorium reserves but little uranium.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-18", "question": "NavIC is the operational name of:", "options": ["India’s weather satellite series", "India’s satellite-based internet service", "The Indian Regional Navigation Satellite System", "ISRO’s deep-space tracking network"], "answer": 2, "explanation": "NavIC (Navigation with Indian Constellation) is the IRNSS, giving position data over India and about 1,500 km around it.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-19", "question": "INS Arihant, commissioned in 2016, is India’s first indigenous:", "options": ["Stealth frigate", "Nuclear-powered ballistic missile submarine", "Aircraft carrier", "Diesel-electric attack submarine"], "answer": 1, "explanation": "INS Arihant is an SSBN that carries nuclear-tipped ballistic missiles, completing India’s land–air–sea nuclear triad. INS Vikrant (2022) is the first indigenous aircraft carrier.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-20", "question": "Which of these is a surface-to-air missile?", "options": ["Nirbhay", "Akash", "Prithvi", "Nag"], "answer": 1, "explanation": "Akash is a surface-to-air missile. Prithvi is a surface-to-surface ballistic missile, Nag an anti-tank missile and Nirbhay a subsonic cruise missile.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-21", "question": "Golden Rice is genetically engineered to be rich in:", "options": ["Lysine", "Vitamin C", "Iron", "Beta-carotene (provitamin A)"], "answer": 3, "explanation": "Golden Rice makes beta-carotene, which the body turns into vitamin A, to fight vitamin A deficiency. Its golden colour comes from the beta-carotene.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-22", "question": "In India, approval for the environmental release of genetically modified crops is given by the:", "options": ["Food Safety and Standards Authority of India", "Department of Biotechnology’s Review Committee on Genetic Manipulation", "Indian Council of Agricultural Research", "Genetic Engineering Appraisal Committee under the Ministry of Environment"], "answer": 3, "explanation": "The GEAC, under the MoEFCC, appraises proposals for the release of GM organisms. The Review Committee on Genetic Manipulation oversees research-stage work.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-23", "question": "India’s first satellite, Aryabhata, was launched from:", "options": ["Thumba", "Sriharikota", "The Soviet Union", "French Guiana"], "answer": 2, "explanation": "Aryabhata went up on a Soviet Kosmos-3M rocket from Kapustin Yar in 1975. India’s own launch capability came with SLV-3 in 1980.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-24", "question": "India’s first indigenous launch vehicle SLV-3 successfully placed which satellite in orbit in 1980?", "options": ["Aryabhata", "Bhaskara-I", "Rohini", "APPLE"], "answer": 2, "explanation": "SLV-3, with A.P.J. Abdul Kalam as project director, put Rohini RS-1 into orbit on 18 July 1980, giving India its own satellite launch capability.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-25", "question": "Match the mission with its main purpose: 1. Chandrayaan-1 (2008)  2. AstroSat (2015)  3. Aditya-L1 (2023)  4. XPoSat (2024); a. Measuring X-ray polarisation from cosmic sources  b. Lunar orbiter that helped detect water molecules on the Moon  c. Study of the Sun  d. Multi-wavelength space observatory", "options": ["1-d, 2-b, 3-c, 4-a", "1-b, 2-d, 3-a, 4-c", "1-b, 2-a, 3-c, 4-d", "1-b, 2-d, 3-c, 4-a"], "answer": 3, "explanation": "Chandrayaan-1 carried NASA’s Moon Mineralogy Mapper, which found water signatures; AstroSat is India’s first multi-wavelength observatory; Aditya-L1 studies the Sun; XPoSat is an X-ray polarimetry satellite.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-26", "question": "How many of these statements about Chandrayaan-3 are correct? I. Its lander was named Vikram and its rover Pragyan. II. It was launched by LVM3. III. India became the first country to soft-land near the Moon’s south pole. IV. India became the first country to soft-land on the Moon.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. India was the fourth country to soft-land on the Moon, after the USSR, the USA and China (IV wrong).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-27", "question": "Match the missile with its type: 1. Prithvi  2. Astra  3. Nag  4. Nirbhay; a. Beyond-visual-range air-to-air missile  b. Anti-tank guided missile  c. Surface-to-surface ballistic missile  d. Long-range subsonic cruise missile", "options": ["1-c, 2-a, 3-d, 4-b", "1-a, 2-c, 3-b, 4-d", "1-c, 2-a, 3-b, 4-d", "1-c, 2-b, 3-a, 4-d"], "answer": 2, "explanation": "Prithvi: short-range surface-to-surface ballistic; Astra: air-to-air BVR; Nag: anti-tank; Nirbhay: subsonic cruise.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-28", "question": "Assertion (A): A geostationary satellite appears fixed over one point on Earth. Reason (R): It orbits in the equatorial plane, in the direction of Earth’s rotation, with a period equal to one rotation of Earth.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: matching Earth’s rotation in the equatorial plane at about 35,786 km altitude keeps the satellite over the same spot.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-29", "question": "Arrange in chronological order: 1. Mars Orbiter Mission  2. Launch of Aryabhata  3. Chandrayaan-1  4. Rohini launched by SLV-3", "options": ["2, 3, 4, 1", "2, 4, 1, 3", "2, 4, 3, 1", "4, 2, 3, 1"], "answer": 2, "explanation": "Aryabhata: 1975; SLV-3/Rohini: 1980; Chandrayaan-1: 2008; Mars Orbiter Mission: 2013.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-30", "question": "How many of these statements are correct? I. The Pokhran tests of May 1998 were code-named Operation Shakti. II. India is a signatory to the Nuclear Non-Proliferation Treaty. III. Tarapur was India’s first nuclear power plant. IV. India has signed the Comprehensive Nuclear-Test-Ban Treaty.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. India has signed neither the NPT nor the CTBT, calling both discriminatory (II and IV wrong). Tarapur began operating in 1969.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-31", "question": "Which of the following is NOT a launch vehicle of ISRO?", "options": ["PSLV", "Vikas", "LVM3", "SSLV"], "answer": 1, "explanation": "Vikas is ISRO’s liquid-fuel rocket engine, used in the PSLV, GSLV and LVM3; it is not a launch vehicle. SSLV, PSLV and LVM3 are all launch vehicles.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-32", "question": "How many of these statements about the PSLV are correct? I. It has four stages. II. Its stages alternate between solid and liquid propulsion. III. In 2017 it placed 104 satellites in orbit in a single mission. IV. It launched Chandrayaan-1 in 2008.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The PSLV’s stages are solid, liquid, solid and liquid; PSLV-C37 launched 104 satellites in February 2017; PSLV-C11 launched Chandrayaan-1 in October 2008.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-33", "question": "Match the cyber term with its meaning: 1. Ransomware  2. Spoofing  3. Botnet  4. Zero-day vulnerability; a. A flaw unknown to the vendor, with no patch yet  b. A network of infected computers controlled remotely  c. Malware that locks or encrypts data and demands payment  d. Disguising a message or website as coming from a trusted source", "options": ["1-c, 2-d, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-b, 4-a", "1-c, 2-b, 3-d, 4-a"], "answer": 2, "explanation": "Ransomware encrypts data for ransom; spoofing fakes the sender’s identity; a botnet is a herd of hijacked machines; a zero-day flaw is exploited before the vendor can fix it.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-34", "question": "Assertion (A): NavIC is a regional rather than a global navigation system. Reason (R): Its satellites are in geostationary and inclined geosynchronous orbits that keep them over India and its surrounding region.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: unlike GPS satellites in medium Earth orbit that circle the globe, NavIC satellites stay over the Indian region, so coverage extends only about 1,500 km beyond India.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-35", "question": "How many of these statements are correct? I. Bt cotton was approved for commercial cultivation in India in 2002. II. Commercial release of Bt brinjal in India has been under a moratorium since 2010. III. Dolly the sheep was the first mammal cloned from an adult body cell. IV. CRISPR-Cas9 is a technique for sequencing genomes.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. CRISPR-Cas9 is a gene-editing tool that cuts DNA at a chosen site; it is not a sequencing method (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-36", "question": "Match the ISRO centre with its location: 1. Vikram Sarabhai Space Centre  2. U R Rao Satellite Centre  3. Space Applications Centre  4. National Remote Sensing Centre; a. Thiruvananthapuram  b. Ahmedabad  c. Hyderabad  d. Bengaluru", "options": ["1-a, 2-d, 3-b, 4-c", "1-a, 2-b, 3-d, 4-c", "1-a, 2-d, 3-c, 4-b", "1-d, 2-a, 3-b, 4-c"], "answer": 0, "explanation": "VSSC (launch vehicles): Thiruvananthapuram; URSC (satellites): Bengaluru; SAC (payloads and applications): Ahmedabad; NRSC (remote-sensing data): Hyderabad.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-37", "question": "Which of the following is NOT an aircraft carrier?", "options": ["INS Vikrant", "INS Arihant", "INS Vikramaditya", "INS Viraat"], "answer": 1, "explanation": "INS Arihant is a nuclear-powered submarine. INS Vikrant (both the 1961 ship and the 2022 indigenous one), INS Vikramaditya and INS Viraat (decommissioned 2017) are carriers.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-38", "question": "How many of these statements are correct? I. One byte is equal to 8 bits. II. An IPv6 address is 128 bits long. III. An IPv4 address is 64 bits long. IV. HTTPS uses port 80 by default.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. IPv4 addresses are 32 bits (III wrong), and HTTPS uses port 443; port 80 is for plain HTTP (IV wrong).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-39", "question": "Assertion (A): Remote-sensing satellites are usually placed in polar sun-synchronous orbits. Reason (R): A sun-synchronous orbit keeps the satellite fixed above one point on Earth.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true, R is false. A sun-synchronous orbit passes over each place at the same local solar time, giving uniform lighting for images, and the polar path covers the whole globe. Staying fixed over one point describes a geostationary orbit.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-40", "question": "Match the nuclear power station with its state: 1. Kudankulam  2. Kakrapar  3. Kaiga  4. Narora; a. Gujarat  b. Tamil Nadu  c. Karnataka  d. Uttar Pradesh", "options": ["1-a, 2-b, 3-c, 4-d", "1-b, 2-c, 3-a, 4-d", "1-b, 2-a, 3-d, 4-c", "1-b, 2-a, 3-c, 4-d"], "answer": 3, "explanation": "Kudankulam: Tamil Nadu (Russian-built VVERs); Kakrapar: Gujarat; Kaiga: Karnataka; Narora: Uttar Pradesh.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-41", "question": "The Indian Space Research Organisation (ISRO) was set up in:", "options": ["1962", "1969", "1975", "1980"], "answer": 1, "explanation": "ISRO was formed on 15 August 1969, replacing INCOSPAR (1962). The Department of Space followed in 1972.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-42", "question": "Gaganyaan is India's programme to:", "options": ["Land a rover on Mars", "Send Indian astronauts into orbit on an Indian rocket", "Build a space telescope", "Launch navigation satellites"], "answer": 1, "explanation": "Gaganyaan aims to carry an Indian crew to low Earth orbit and bring them back safely, using a human-rated LVM3.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-43", "question": "Tejas, built by Hindustan Aeronautics Limited, is India's indigenous:", "options": ["Light combat aircraft", "Attack helicopter", "Aircraft carrier", "Cruise missile"], "answer": 0, "explanation": "Tejas is the Light Combat Aircraft (LCA) designed by ADA and built by HAL; it entered IAF service in 2016.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-44", "question": "The Defence Research and Development Organisation (DRDO) has its headquarters in:", "options": ["Bengaluru", "Hyderabad", "New Delhi", "Pune"], "answer": 2, "explanation": "DRDO, formed in 1958, is headquartered at DRDO Bhawan, New Delhi. Bengaluru is ISRO's headquarters, which makes it the tempting wrong answer.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-45", "question": "Who, later the 11th President of India, is called the 'Missile Man of India'?", "options": ["Homi Bhabha", "A. P. J. Abdul Kalam", "Vikram Sarabhai", "Satish Dhawan"], "answer": 1, "explanation": "Dr Kalam led the SLV-3 project at ISRO and then DRDO's Integrated Guided Missile Development Programme (Agni, Prithvi, Akash, Trishul, Nag).", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-46", "question": "INS Vikrant, commissioned in September 2022, is notable as:", "options": ["India's first nuclear submarine", "India's first indigenously built aircraft carrier", "India's largest destroyer", "A former Russian carrier"], "answer": 1, "explanation": "The new INS Vikrant was designed by the Navy and built at Cochin Shipyard. INS Vikramaditya is the former Russian Admiral Gorshkov.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-47", "question": "Chandrayaan-2 (2019) lost its lander Vikram during the descent. Which part of the mission continues to work?", "options": ["The rover Pragyan", "The orbiter", "The lander's seismometer", "Nothing; the mission ended"], "answer": 1, "explanation": "The Chandrayaan-2 orbiter kept circling the Moon and even served as a communication backup for Chandrayaan-3's lander in 2023.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-48", "question": "With the SpaDeX mission, India in January 2025 became the fourth country to:", "options": ["Land on the Moon", "Dock two spacecraft in orbit", "Send a probe to Mars", "Launch a space station module"], "answer": 1, "explanation": "SpaDeX docked two small satellites (SDX01 and SDX02) on 16 January 2025, after the USA, Russia and China.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-49", "question": "In computing, a 'firewall' is used to:", "options": ["Cool the processor", "Monitor and control network traffic according to security rules", "Recover deleted files", "Speed up the internet connection"], "answer": 1, "explanation": "A firewall, in hardware or software, filters incoming and outgoing traffic to block unauthorised access.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-50", "question": "The Bhabha Atomic Research Centre (BARC) is located at:", "options": ["Kalpakkam", "Tarapur", "Trombay, Mumbai", "Narora"], "answer": 2, "explanation": "BARC is at Trombay in Mumbai. Kalpakkam hosts the Indira Gandhi Centre for Atomic Research, while Tarapur and Narora are power stations.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-51", "question": "In February 2017 ISRO set a record by launching how many satellites on a single rocket (PSLV-C37)?", "options": ["83", "104", "130", "143"], "answer": 1, "explanation": "PSLV-C37 placed 104 satellites in orbit, most of them small foreign satellites. SpaceX later exceeded this with 143 on one rocket in 2021.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-52", "question": "CRISPR-Cas9 is a technology used for:", "options": ["Editing genes at specific locations in DNA", "Producing nuclear fuel", "Storing data in the cloud", "Detecting gravitational waves"], "answer": 0, "explanation": "CRISPR-Cas9 acts like molecular scissors guided by RNA to cut DNA at a chosen site; Charpentier and Doudna won the 2020 Chemistry Nobel for it.", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "gk-science-tech-53", "question": "The Unified Payments Interface (UPI) was developed by:", "options": ["The Reserve Bank of India", "The State Bank of India", "The National Payments Corporation of India", "The Ministry of Electronics and IT"], "answer": 2, "explanation": "NPCI, an RBI-promoted body owned by banks, launched UPI in 2016. RBI regulates the system but did not build it.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-54", "question": "Rafale fighter aircraft bought by the Indian Air Force are made in:", "options": ["Russia", "France", "Sweden", "United States"], "answer": 1, "explanation": "Rafale is made by Dassault Aviation of France; the first jets reached India in 2020.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-55", "question": "Which ISRO launch vehicle was developed specifically to place small satellites (up to about 500 kg) in low Earth orbit at short notice?", "options": ["PSLV", "GSLV", "SSLV", "LVM3"], "answer": 2, "explanation": "The Small Satellite Launch Vehicle is a three-stage solid rocket with a liquid trim module; its first successful flight was SSLV-D2 in February 2023.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-56", "question": "Pralay, developed by DRDO, is a:", "options": ["Long-range cruise missile", "Short-range quasi-ballistic surface-to-surface missile", "Anti-tank missile", "Submarine-launched ballistic missile"], "answer": 1, "explanation": "Pralay is a conventional short-range quasi-ballistic missile that can manoeuvre in flight to evade interceptors.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-57", "question": "'Prachand', inducted into the Indian Air Force in October 2022, is:", "options": ["An indigenous light combat helicopter", "A main battle tank", "A stealth frigate", "An unmanned aerial vehicle"], "answer": 0, "explanation": "Prachand is HAL's Light Combat Helicopter, designed to operate at very high altitudes such as the Siachen region.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-58", "question": "The Prototype Fast Breeder Reactor at Kalpakkam uses:", "options": ["Natural uranium fuel and heavy water coolant", "Uranium–plutonium mixed oxide fuel and liquid sodium coolant", "Thorium fuel and light water coolant", "Enriched uranium fuel and helium coolant"], "answer": 1, "explanation": "The 500 MWe PFBR runs on U–Pu MOX fuel cooled by liquid sodium; it belongs to the second stage of India's nuclear programme. Heavy water is used in the first-stage PHWRs.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-59", "question": "Vyommitra, associated with the Gaganyaan programme, is:", "options": ["The crew capsule", "A female humanoid robot to fly on uncrewed test missions", "The tracking ship", "The astronaut training centre"], "answer": 1, "explanation": "Vyommitra is a half-humanoid robot that will monitor the crew module on uncrewed flights before astronauts fly.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-60", "question": "Shukrayaan, ISRO's planned mission approved by the Union Cabinet in 2024, is meant to study:", "options": ["Mercury", "Venus", "Jupiter's moons", "An asteroid"], "answer": 1, "explanation": "The Venus Orbiter Mission (Shukrayaan) will study Venus's surface, atmosphere and its interaction with the Sun. 'Shukra' is the Sanskrit name for Venus.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-61", "question": "The National Quantum Mission, to develop quantum computing, communication and sensing, was approved by the Union Cabinet in:", "options": ["2019", "2021", "2023", "2025"], "answer": 2, "explanation": "The Cabinet approved the mission in April 2023 with an outlay of about Rs 6,000 crore over eight years (2023–31).", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-62", "question": "The PARAM series of supercomputers is developed by:", "options": ["ISRO", "C-DAC", "DRDO", "IIT Bombay"], "answer": 1, "explanation": "The Centre for Development of Advanced Computing built PARAM 8000 (1991) and later systems under the National Supercomputing Mission.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-63", "question": "Agni-Prime (Agni-P), tested by DRDO, is a:", "options": ["New-generation, canister-launched medium-range ballistic missile", "Surface-to-air missile", "Hypersonic glide vehicle", "Ship-launched cruise missile"], "answer": 0, "explanation": "Agni-Prime is a two-stage, solid-fuel, nuclear-capable ballistic missile with a range of 1,000–2,000 km, launched from a canister for quick deployment.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-64", "question": "NISAR, the Earth-observation radar satellite launched on a GSLV in July 2025, was built jointly by ISRO and:", "options": ["ESA", "JAXA", "NASA", "Roscosmos"], "answer": 2, "explanation": "NASA-ISRO Synthetic Aperture Radar carries NASA's L-band and ISRO's S-band radar to map changes in land, ice and vegetation.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-65", "question": "India plans to complete its own space station, the Bharatiya Antariksh Station, by:", "options": ["2028", "2030", "2035", "2040"], "answer": 2, "explanation": "The government's plan is for the first module (BAS-1) around 2028 and the full station by 2035, with an Indian on the Moon by 2040.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-66", "question": "IN-SPACe, set up in 2020, is:", "options": ["ISRO's new launch pad", "A single-window agency that authorises and promotes private space activities", "India's space defence command", "A satellite navigation system"], "answer": 1, "explanation": "The Indian National Space Promotion and Authorisation Centre, under the Department of Space, authorises and hand-holds non-government space companies.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-67", "question": "Agnikul Cosmos's Agnibaan SOrTeD, launched in May 2024, was notable for using:", "options": ["The world's first single-piece 3D-printed semi-cryogenic engine", "A nuclear thermal engine", "A reusable first stage that landed at sea", "Solar sails"], "answer": 0, "explanation": "Its Agnilet engine, printed in one piece, burns kerosene with liquid oxygen; it flew from Agnikul's private launch pad at Sriharikota.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-68", "question": "Arrange in chronological order: 1. SpaDeX docking 2. Chandrayaan-3 landing 3. Mars Orbiter Mission enters Mars orbit 4. PSLV-C37 launches 104 satellites", "options": ["3-4-2-1", "4-3-2-1", "3-2-4-1", "3-4-1-2"], "answer": 0, "explanation": "MOM entered Mars orbit in September 2014; PSLV-C37 flew in February 2017; Chandrayaan-3 landed in August 2023; SpaDeX docked in January 2025.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-69", "question": "Match the mission or vehicle with its purpose: A. Vikram-S B. Pushpak (RLV-LEX) C. Gaganyaan TV-D1 D. POEM — 1. Test of the crew escape system 2. Using the spent fourth stage of PSLV as an orbital platform 3. First privately built rocket launched from India 4. Autonomous landing test of a reusable winged vehicle", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-3, B-1, C-4, D-2"], "answer": 2, "explanation": "Vikram-S (Skyroot, November 2022) – first private rocket; Pushpak – RLV landing experiments; TV-D1 (October 2023) – crew escape test; POEM – PSLV Orbital Experimental Module.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-70", "question": "How many of these statements about the Gaganyaan programme are correct? I. The four astronaut-designates named in 2024 are Indian Air Force officers. II. The crew is to fly on a human-rated version of LVM3. III. The crew module is planned for a low Earth orbit of about 400 km. IV. With it India would be the third nation to send humans into space on its own.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. India would be the fourth, after the USSR, the USA and China.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-71", "question": "Match the naval vessel with its type: A. INS Vikramaditya B. INS Arighaat C. INS Vagsheer D. INS Surat — 1. Guided-missile destroyer 2. Diesel-electric attack submarine 3. Nuclear-powered ballistic missile submarine 4. Aircraft carrier", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Vikramaditya – aircraft carrier (ex-Admiral Gorshkov); Arighaat (2024) – second Arihant-class SSBN; Vagsheer (2025) – Kalvari (Scorpene) class submarine; Surat (2025) – Project 15B destroyer.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-72", "question": "Assertion (A): Geostationary satellites give poor coverage of the polar regions. Reason (R): They stay above the equator, so from high latitudes they appear very low on the horizon or not at all.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: beyond about 81° latitude a geostationary satellite is below the horizon, which is why polar coverage needs other orbits.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-73", "question": "Assertion (A): A fast breeder reactor can produce more fissile material than it consumes. Reason (R): Fast neutrons in it convert fertile uranium-238 into fissile plutonium-239.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: breeding comes from the conversion of U-238 in the blanket into Pu-239, which is why breeders form India's second stage.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-74", "question": "How many of these statements are correct? I. HTTPS secures web traffic using TLS encryption. II. RAM keeps its data when the power is switched off. III. ROM loses its contents when the power is switched off. IV. Linux is an open-source operating system.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and IV are correct. RAM is volatile (loses data without power) and ROM is non-volatile, the reverse of statements II and III.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-75", "question": "Match the term with its meaning: A. Li-Fi B. Edge computing C. Deepfake D. Quantum key distribution — 1. AI-generated fake audio or video of real people 2. Processing data near where it is produced rather than in a distant data centre 3. Sharing encryption keys using quantum states, so eavesdropping is detectable 4. Wireless data transfer using light", "options": ["A-4, B-2, C-3, D-1", "A-4, B-2, C-1, D-3", "A-2, B-4, C-1, D-3", "A-4, B-1, C-2, D-3"], "answer": 1, "explanation": "Li-Fi uses visible or infrared light; edge computing cuts delay by processing locally; deepfakes are synthetic media; QKD relies on the fact that measuring a quantum state disturbs it.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-76", "question": "Which pair of mission and target is NOT correctly matched?", "options": ["Mangalyaan — Mars", "Chandrayaan-3 — Moon", "Aditya-L1 — Sun", "XPoSat — Venus"], "answer": 3, "explanation": "XPoSat (January 2024) is an X-ray polarimetry satellite in low Earth orbit studying cosmic X-ray sources such as black holes and pulsars. India's Venus mission is Shukrayaan.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-77", "question": "How many of these statements about Aditya-L1 are correct? I. It was launched by a PSLV. II. It carries seven payloads. III. One of its payloads, VELC, is a coronagraph. IV. It is India's first space-based solar observatory.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: launched on PSLV-C57 in September 2023, it carries seven instruments, including the Visible Emission Line Coronagraph, and is India's first solar mission.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-78", "question": "Arrange in chronological order: 1. Operation Shakti tests at Pokhran 2. Smiling Buddha test 3. Commissioning of INS Arihant 4. Mission Shakti anti-satellite test", "options": ["1-2-3-4", "2-1-4-3", "2-3-1-4", "2-1-3-4"], "answer": 3, "explanation": "Smiling Buddha May 1974; Operation Shakti May 1998; INS Arihant commissioned 2016; Mission Shakti ASAT test March 2019.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-79", "question": "How many of these statements are correct? I. DNA fingerprinting was developed by Alec Jeffreys. II. Dolly the sheep was cloned in the United States. III. Human insulin was the first recombinant-DNA drug approved for use (1982). IV. The first approved gene therapy trial (1990) treated ADA deficiency.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. Dolly was cloned at the Roslin Institute in Scotland (born 1996).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "gk-science-tech-80", "question": "Assertion (A): GPS satellites move in medium Earth orbit. Reason (R): Geostationary satellites orbit at about 36,000 km above the equator.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true (GPS satellites fly at about 20,200 km), but the height of geostationary satellites does not explain why GPS uses medium Earth orbit.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-81", "question": "Match the scientist with the role: A. Homi J. Bhabha B. Satish Dhawan C. Vikram Sarabhai D. A. P. J. Abdul Kalam — 1. Project director of SLV-3 2. Founder of TIFR and first chairman of the Atomic Energy Commission 3. Founder of the Physical Research Laboratory, Ahmedabad 4. Chairman of ISRO from 1972 to 1984", "options": ["A-2, B-4, C-3, D-1", "A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-2, B-4, C-1, D-3"], "answer": 0, "explanation": "Bhabha set up TIFR (1945) and chaired the AEC (1948); Dhawan led ISRO 1972–84; Sarabhai founded PRL (1947); Kalam directed SLV-3, which orbited Rohini in 1980.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-82", "question": "How many of these statements are correct? I. CERT-In is India's national agency for responding to cyber security incidents. II. India's main law on electronic records and cyber crime is the Information Technology Act, 2000. III. The Digital Personal Data Protection Act was enacted in 2023. IV. The Supreme Court struck down Section 66A of the IT Act in 2015.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Section 66A was struck down in Shreya Singhal v. Union of India (2015) as violating free speech.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-83", "question": "Which one of the following missiles was NOT developed by DRDO?", "options": ["Agni", "Prithvi", "Akash", "Igla"], "answer": 3, "explanation": "Igla is a Russian shoulder-fired surface-to-air missile used by Indian forces. Agni, Prithvi and Akash came from DRDO's guided missile programme.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-84", "question": "Match the satellite series with its main use: A. GSAT B. Cartosat C. RISAT D. Oceansat — 1. Radar imaging in all weather 2. Study of oceans and winds 3. Communication 4. High-resolution mapping", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "GSAT – communication; Cartosat – cartography and high-resolution imagery; RISAT – synthetic aperture radar imaging through clouds; Oceansat – ocean colour and winds.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-85", "question": "Assertion (A): The fourth stage of the PSLV uses cryogenic propulsion. Reason (R): Cryogenic stages burn liquid hydrogen with liquid oxygen.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: PSLV's fourth stage (PS4) uses storable liquid propellants (MMH and mixed oxides of nitrogen); cryogenic stages are on GSLV and LVM3. R is true.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-86", "question": "The World Wide Web was invented in 1989 by:", "options": ["Bill Gates", "Tim Berners-Lee", "Vint Cerf", "Steve Jobs"], "answer": 1, "explanation": "Tim Berners-Lee proposed the Web at CERN, creating HTML, HTTP and URLs. Vint Cerf co-designed the TCP/IP protocols of the internet, which the Web runs on.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-87", "question": "In web addresses, URL stands for:", "options": ["Universal Routing Link", "Unified Resource Line", "Uniform Resource Locator", "User Request Location"], "answer": 2, "explanation": "A Uniform Resource Locator gives the address of a resource on the web, such as https://www.example.com/page.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-88", "question": "Which ISRO launch vehicle is often called its “workhorse” because of its long record of successful launches?", "options": ["SLV-3", "ASLV", "SSLV", "PSLV"], "answer": 3, "explanation": "The Polar Satellite Launch Vehicle has launched Chandrayaan-1, the Mars Orbiter Mission and many foreign satellites. SLV-3 and ASLV were early vehicles, and SSLV is for small satellites.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-89", "question": "“Cloud computing” refers to:", "options": ["Delivering computing services such as storage and software over the internet on demand", "Using satellites to forecast weather", "Storing data only on a personal hard disk", "Computers powered by solar energy"], "answer": 0, "explanation": "In cloud computing, users rent servers, storage or applications from remote data centres instead of owning the hardware, paying for what they use.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "gk-science-tech-90", "question": "A blockchain is best described as:", "options": ["A chain of computers linked by cables", "A central database controlled by a single bank", "A distributed, tamper-resistant ledger in which records are linked cryptographically in blocks", "A type of computer virus"], "answer": 2, "explanation": "Each block carries a cryptographic hash of the previous one, and copies are held by many participants, so altering past records is very hard. Cryptocurrencies are one application.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "gk-science-tech-91", "question": "IPv6 was introduced mainly because IPv4 was running out of addresses. How long is an IPv6 address?", "options": ["32 bits", "64 bits", "48 bits", "128 bits"], "answer": 3, "explanation": "IPv4 uses 32-bit addresses (about 4.3 billion), while IPv6 uses 128-bit addresses, giving an almost unlimited number. 48 bits is the length of a MAC address.", "difficulty": "hard", "source": "IBPS PO · SSC CGL"},
  {"id": "gk-science-tech-92", "question": "LiDAR, used in self-driving cars and terrain mapping, measures distances using:", "options": ["Pulses of laser light and the time they take to return", "Radio waves reflected from objects", "Sound waves in water", "Gravity variations"], "answer": 0, "explanation": "Light Detection and Ranging times the echoes of laser pulses to build detailed 3-D maps. Radar uses radio waves and sonar uses sound.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "gk-science-tech-93", "question": "Which statement best describes the relation between artificial intelligence (AI) and machine learning (ML)?", "options": ["They are unrelated fields", "ML is a branch of AI in which systems learn patterns from data instead of following only hand-written rules", "AI is a branch of ML", "ML deals only with robots' hardware"], "answer": 1, "explanation": "AI is the broad goal of machines performing tasks that need intelligence; ML is one approach to it, and deep learning, using many-layered neural networks, is a subset of ML.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "gk-science-tech-94", "question": "A vehicle or missile is described as hypersonic when its speed exceeds about:", "options": ["Mach 1", "Mach 2", "Mach 5", "Mach 25"], "answer": 2, "explanation": "Speeds above about five times the speed of sound are called hypersonic. Between Mach 1 and Mach 5 the flight is supersonic; BrahMos, for instance, flies at around Mach 2.8.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "gk-science-tech-95", "question": "Two-factor authentication improves account security by:", "options": ["Asking for the same password twice", "Making the password longer", "Encrypting the hard disk", "Requiring two different kinds of proof, such as a password and a one-time code sent to the user's phone"], "answer": 3, "explanation": "It combines something you know (password) with something you have (phone, token) or something you are (fingerprint), so a stolen password alone is not enough.", "difficulty": "hard", "source": "IBPS PO · SSC CGL"},
  {"id": "gk-science-tech-96", "question": "Match the orbit with a typical use. A. Low Earth orbit (a few hundred km)  B. Medium Earth orbit (about 20,000 km)  C. Geostationary orbit (about 36,000 km)  D. Sun-synchronous polar orbit; 1. Earth-observation satellites that pass over a place at the same local time  2. Communication and weather satellites fixed over one longitude  3. GPS navigation satellites  4. The International Space Station", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "The ISS circles at about 400 km; GPS satellites orbit at about 20,200 km; geostationary satellites at 35,786 km above the equator; remote-sensing satellites such as Cartosat use sun-synchronous polar orbits.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-97", "question": "How many of these statements about missiles are correct? I. A ballistic missile is powered only in its early phase and then follows a largely free-falling arc. II. A cruise missile is powered for most of its flight and stays within the atmosphere. III. BrahMos is a cruise missile. IV. The Agni series consists of cruise missiles.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. Agni missiles are ballistic missiles of increasing range, so IV is wrong; Nirbhay is India's subsonic cruise missile.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-98", "question": "Assertion (A): A cryogenic upper stage lets a rocket place heavier satellites in high orbits than a stage of the same mass using conventional propellants. Reason (R): Liquid hydrogen burnt with liquid oxygen gives a very high exhaust velocity (high specific impulse).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Higher exhaust velocity means more thrust per kilogram of propellant, which matters most in the upper stage; that is why GSLV and LVM3 needed cryogenic stages to reach geostationary transfer orbit with heavy payloads.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-99", "question": "How many of these statements about quantum computing are correct? I. A qubit can exist in a superposition of 0 and 1. II. Entanglement links the states of qubits so that they cannot be described independently. III. A large enough quantum computer running Shor's algorithm could break widely used RSA encryption. IV. Quantum computers are expected to replace classical computers for all everyday tasks.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct, which is why post-quantum cryptography is being developed. Quantum machines excel only at certain problems, such as factoring or simulating molecules, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-100", "question": "Assertion (A): A scramjet engine cannot start working from a standstill. Reason (R): It has no rotating compressor and depends on air entering at very high speed to compress it, with combustion taking place in supersonic airflow.", "options": ["A is true but R is false", "A is false but R is true", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "Scramjets rely on ram compression, so a rocket or other engine must first accelerate the vehicle to high Mach numbers; ISRO tested a scramjet on a sounding rocket in 2016.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-101", "question": "In computing, HTML stands for:", "options": ["HyperText Markup Language", "High-Level Text Machine Language", "Hyperlink and Text Management Language", "Home Tool Markup Language"], "answer": 0, "explanation": "HTML (HyperText Markup Language) describes the structure of web pages. It was created by Tim Berners-Lee along with HTTP and URLs.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-102", "question": "APPLE, launched in 1981 on an Ariane rocket, was India's first:", "options": ["Remote-sensing satellite", "Experimental geostationary communication satellite", "Satellite launched by an Indian rocket", "Weather satellite"], "answer": 1, "explanation": "APPLE (Ariane Passenger PayLoad Experiment) was an experimental communication satellite placed in geostationary orbit. Rohini (1980) was the first launched by an Indian rocket and Bhaskara-I an early Earth-observation satellite.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-103", "question": "India's first sounding rocket was launched in November 1963 from:", "options": ["Balasore", "Sriharikota", "Thumba", "Kourou"], "answer": 2, "explanation": "A Nike-Apache rocket lifted off from the Thumba Equatorial Rocket Launching Station near Thiruvananthapuram, chosen because it lies close to the magnetic equator. Sriharikota came into use only in 1971.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-104", "question": "Arrange in chronological order: 1. Rakesh Sharma's spaceflight  2. Launch of Sputnik 1  3. Apollo 11 Moon landing  4. Yuri Gagarin's orbital flight", "options": ["2-4-1-3", "4-2-3-1", "2-3-4-1", "2-4-3-1"], "answer": 3, "explanation": "Sputnik 1 was launched in 1957, Gagarin orbited Earth in 1961, Apollo 11 landed on the Moon in 1969 and Rakesh Sharma flew aboard Soyuz T-11 in 1984.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-105", "question": "GPS, used for satellite navigation, stands for:", "options": ["Global Positioning System", "General Packet Service", "Geographic Position Sensor", "Global Path Satellite"], "answer": 0, "explanation": "GPS, the Global Positioning System, is a US satellite navigation system. India's regional counterpart is NavIC.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-106", "question": "The Satellite Instructional Television Experiment (SITE) of 1975–76, which beamed educational programmes to Indian villages, used:", "options": ["India's Aryabhata satellite", "NASA's ATS-6 satellite", "INSAT-1A", "A Soviet Molniya satellite"], "answer": 1, "explanation": "SITE used the American ATS-6 satellite to reach about 2,400 villages. Aryabhata was a scientific satellite and INSAT-1A came only in 1982.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-107", "question": "Kalpana Chawla lost her life in 2003 when which space shuttle broke up on re-entry?", "options": ["Discovery", "Challenger", "Columbia", "Atlantis"], "answer": 2, "explanation": "Columbia (mission STS-107) disintegrated over Texas on 1 February 2003. Challenger exploded shortly after launch in 1986.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-108", "question": "Match the defence system with its type. A. Arjun  B. Pinaka  C. Dhanush  D. Netra; 1. Airborne early warning and control system  2. 155 mm towed artillery gun  3. Multi-barrel rocket launcher  4. Main battle tank", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Arjun is DRDO's main battle tank, Pinaka a multi-barrel rocket launcher, Dhanush a 155 mm towed howitzer, and Netra an airborne early warning and control system mounted on an Embraer jet.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-109", "question": "The Integrated Guided Missile Development Programme, which produced Prithvi, Agni, Akash, Trishul and Nag, was launched in:", "options": ["1983", "1974", "1990", "1998"], "answer": 0, "explanation": "DRDO launched the IGMDP in 1983 under A.P.J. Abdul Kalam. 1974 and 1998 were the years of the Pokhran nuclear tests.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-110", "question": "How many of these statements about India's nuclear programme are correct? I. APSARA at Trombay, which went critical in 1956, was the first research reactor in Asia. II. Kudankulam's reactors were built with Russian collaboration. III. The first two units at Tarapur are boiling water reactors supplied by the United States. IV. The CIRUS research reactor was supplied by France.", "options": ["Only two", "Only three", "Only one", "All four"], "answer": 1, "explanation": "I, II and III are correct; Tarapur's two General Electric BWRs began operating in 1969. CIRUS (Canada-India Reactor Utility Services) came from Canada, with heavy water supplied by the US, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-111", "question": "INSAT, the satellite system used for telecommunication, broadcasting and meteorology, stands for:", "options": ["Indian Navigation Satellite", "International Network Satellite", "Indian National Satellite System", "Integrated National Space and Telecom"], "answer": 2, "explanation": "INSAT is the Indian National Satellite System; its first satellite, INSAT-1A, went up in 1982. NavIC is India's navigation system.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-112", "question": "The Turing test, proposed in 1950, is meant to judge whether:", "options": ["A processor has enough memory for a task", "A computer program will ever finish running", "A code can be cracked within a fixed time", "A machine can show behaviour indistinguishable from a human's in conversation"], "answer": 3, "explanation": "Alan Turing proposed the ‘imitation game’ in his 1950 paper ‘Computing Machinery and Intelligence’. Whether a program halts is the separate halting problem, which he also studied.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-113", "question": "In a computer, CPU stands for:", "options": ["Central Processing Unit", "Central Program Utility", "Computer Peripheral Unit", "Control Power Unit"], "answer": 0, "explanation": "The Central Processing Unit carries out program instructions; it is often called the brain of the computer.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-114", "question": "INS Kalvari, commissioned in 2017, is the first of India's:", "options": ["Indigenous nuclear-powered ballistic missile submarines", "Scorpène-class submarines built under Project 75", "Stealth guided-missile frigates", "Kolkata-class destroyers"], "answer": 1, "explanation": "Kalvari is the first of six Scorpène-class diesel-electric submarines built by Mazagon Dock with French help under Project 75. INS Arihant is the first indigenous SSBN.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-115", "question": "Assertion (A): Rockets are preferably launched towards the east from sites close to the equator. Reason (R): The Earth's eastward rotational speed is greatest at the equator and adds to the rocket's velocity.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Surface speed due to rotation is about 465 m/s at the equator and falls towards the poles; an eastward launch near the equator gains this free boost, which is one reason Sriharikota and Kourou were chosen.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-116", "question": "Antrix Corporation, set up in 1992, is:", "options": ["A private satellite launch company", "DRDO's missile production unit", "India's space regulator", "The commercial arm of ISRO"], "answer": 3, "explanation": "Antrix markets ISRO's products and services abroad. IN-SPACe is the authorisation body set up in 2020, and DRDO has no link with Antrix.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-117", "question": "Match the internet protocol with its job. A. SMTP  B. FTP  C. DNS  D. DHCP; 1. Assigning IP addresses to devices automatically  2. Translating domain names into IP addresses  3. Transferring files  4. Sending e-mail", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1"], "answer": 0, "explanation": "SMTP sends e-mail, FTP transfers files, DNS turns names such as example.com into IP addresses, and DHCP hands out IP addresses on a network.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-118", "question": "How many of these statements about computing history are correct? I. Charles Babbage designed the Analytical Engine. II. Ada Lovelace is regarded as the first computer programmer. III. ENIAC, an early electronic computer, was built in Britain. IV. Moore's law says processor clock speed doubles every year.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. ENIAC was built at the University of Pennsylvania in the US (1945), and Moore's law concerns the number of transistors on a chip doubling roughly every two years, so III and IV are wrong.", "difficulty": "very-hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-119", "question": "Lakshya, developed by DRDO, is a:", "options": ["Light combat helicopter", "Main battle tank", "Pilotless target aircraft", "Anti-ship cruise missile"], "answer": 2, "explanation": "Lakshya is a reusable pilotless target aircraft used for training gun and missile crews. Arjun is a tank and Prachand a light combat helicopter.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-120", "question": "ARPANET, the network regarded as the forerunner of the internet, was developed in the late 1960s by the:", "options": ["International Telecommunication Union", "European Organization for Nuclear Research (CERN)", "British Post Office", "US Department of Defense"], "answer": 3, "explanation": "ARPANET was funded by the US Defense Department's Advanced Research Projects Agency and first linked computers in 1969. CERN is where the World Wide Web was later invented.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-121", "question": "How many of these statements about orbits and spaceflight are correct? I. The Kármán line, often taken as the edge of space, is about 100 km above sea level. II. The International Space Station orbits at roughly 400 km. III. Escape velocity from Earth's surface is about 11.2 km/s. IV. A satellite in a lower orbit moves more slowly than one in a higher orbit.", "options": ["Only three", "Only two", "Only one", "All four"], "answer": 0, "explanation": "I, II and III are correct. The lower the orbit, the stronger gravity's pull and the faster a satellite must move, so IV is wrong; an ISS-height orbit takes about 90 minutes.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-122", "question": "INS Chakra, the nuclear-powered attack submarine operated by the Indian Navy, was obtained on lease from:", "options": ["France", "Russia", "The United States", "The United Kingdom"], "answer": 1, "explanation": "India leased a Soviet Charlie-class submarine as INS Chakra in 1988 and a Russian Akula-class boat under the same name in 2012. India's own Arihant-class boats are ballistic-missile submarines.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-123", "question": "Assertion (A): India's pressurised heavy water reactors can run on natural uranium. Reason (R): Heavy water slows neutrons down while absorbing very few of them.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Because heavy water absorbs so few neutrons, enough remain to sustain a chain reaction in natural uranium (about 0.7% U-235). Light-water reactors absorb more and need enriched fuel.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-124", "question": "Bhaskara-I (1979), India's experimental Earth-observation satellite, was launched from:", "options": ["The United States", "Sriharikota", "French Guiana", "The Soviet Union"], "answer": 3, "explanation": "Like Aryabhata, Bhaskara-I went up on a Soviet Intercosmos rocket, from Kapustin Yar. The first launch from Sriharikota to reach orbit was Rohini in 1980.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-125", "question": "Match the space telescope with the band of light it was mainly built to observe. A. Hubble  B. Chandra  C. Spitzer  D. Fermi; 1. Gamma rays  2. Infrared  3. X-rays  4. Visible and ultraviolet", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Hubble works mainly in visible and ultraviolet light, Chandra observes X-rays, Spitzer was an infrared telescope, and Fermi studies gamma rays. All four are NASA missions.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"gk-science-tech-126","question":"Before ISRO was formed in 1969, India's space research was guided by the Indian National Committee for Space Research (INCOSPAR), set up in 1962 under the:","options":["Department of Space","Department of Atomic Energy","Council of Scientific and Industrial Research","Ministry of Defence"],"answer":1,"explanation":"INCOSPAR was formed under the DAE with Vikram Sarabhai as chairman. The Department of Space and the Space Commission came only in 1972.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-127","question":"Arrange in chronological order: 1. Department of Space set up  2. INCOSPAR formed  3. ISRO formed  4. First sounding rocket launched from Thumba","options":["2-3-4-1","2-4-3-1","4-2-3-1","2-4-1-3"],"answer":1,"explanation":"INCOSPAR (1962), first Thumba launch (November 1963), ISRO (August 1969) and the Department of Space (1972), which took ISRO under it.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-128","question":"The first sounding rocket launched from Thumba, on 21 November 1963, was:","options":["A Rohini RH-75 sounding rocket built entirely in India","A Centaure rocket supplied by France","An M-100 rocket supplied by the Soviet Union","A Nike-Apache rocket supplied by the United States"],"answer":3,"explanation":"The first launch was an American Nike-Apache. French Centaure rockets were later made under licence, and the first fully Indian sounding rocket, the RH-75, flew in 1967.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-129","question":"Thumba, near Thiruvananthapuram, was chosen for India's first rocket launching station mainly because it lies:","options":["On the east coast, so rockets could fall safely into the Bay of Bengal","Very close to the magnetic equator, ideal for studying the equatorial electrojet","At India's southern tip, giving the largest possible boost from the Earth's rotation","Far from any settlement, so no villagers had to be moved from the site"],"answer":1,"explanation":"Thumba sits almost on the Earth's magnetic equator, valuable for upper-atmosphere and ionosphere research. It is on the west coast, and a fishing village and church had to be relocated.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-130","question":"SLV-3, which placed Rohini in orbit in July 1980, was a:","options":["Three-stage vehicle with liquid-fuelled second and third stages","Four-stage vehicle with all four stages using solid propellant","Two-stage vehicle with a small cryogenic upper stage","Four-stage vehicle alternating solid and liquid stages"],"answer":1,"explanation":"SLV-3 was an all-solid, four-stage rocket able to put about 40 kg into low orbit. Alternating solid and liquid stages is the PSLV's design.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-131","question":"The Augmented Satellite Launch Vehicle (ASLV), flown four times between 1987 and 1994, was mainly meant to prove:","options":["Strap-on booster technology and closed-loop guidance","Cryogenic propulsion needed for geostationary launches","Winged reusable launch vehicle technology for landing","The liquid Vikas engine in a large liquid core stage"],"answer":0,"explanation":"ASLV added two strap-on boosters to an SLV-3-type core to test strap-on and closed-loop guidance technology; its last two flights put SROSS satellites in orbit.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-132","question":"Match the PSLV variant with its configuration. A. PSLV-CA  B. PSLV-DL  C. PSLV-QL  D. PSLV-XL; 1. Six extended strap-on boosters  2. No strap-on boosters  3. Four strap-on boosters  4. Two strap-on boosters","options":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-1, B-4, C-3, D-2","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"CA is 'core alone' with no strap-ons, DL has two, QL four and XL six extended strap-ons for the heaviest payloads.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-133","question":"Which PSLV variant launched both Chandrayaan-1 (2008) and the Mars Orbiter Mission (2013)?","options":["PSLV-CA","PSLV-DL","PSLV-XL","PSLV-QL"],"answer":2,"explanation":"Both missions needed the extra thrust of the XL version with six extended strap-on boosters (PSLV-C11 and PSLV-C25).","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-134","question":"The Vikas liquid engine, used in the PSLV, GSLV and LVM3, was developed from which foreign engine under a technology arrangement with France?","options":["Vulcain","Viking","RD-180","HM7"],"answer":1,"explanation":"Vikas is derived from the Viking engine of the Ariane rockets. Vulcain and HM7 are Ariane's cryogenic engines and the RD-180 is Russian.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-135","question":"India first flew its own cryogenic upper stage successfully in January 2014 on:","options":["GSLV-D3, which carried GSAT-4","LVM3-X, which carried the CARE module","GSLV-F01, which carried EDUSAT","GSLV-D5, which carried GSAT-14"],"answer":3,"explanation":"GSLV-D5 succeeded with the indigenous cryogenic upper stage. The first attempt, GSLV-D3 in 2010, failed; early GSLVs such as the one for EDUSAT used Russian cryogenic stages, and LVM3-X flew a passive cryogenic stage.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-136","question":"In the early 1990s, the transfer of cryogenic engine technology to ISRO from Russia's Glavkosmos was blocked mainly because of:","options":["US objections and sanctions citing the Missile Technology Control Regime","A UN Security Council embargo imposed after India's nuclear tests","Cuts in the Russian space budget after the Soviet Union broke up","A licensing dispute with France over the Ariane cryogenic engine"],"answer":0,"explanation":"The US sanctioned ISRO and Glavkosmos in 1992 under MTCR rules, so Russia supplied ready-made stages but not the technology, and ISRO developed its own cryogenic stage. The Pokhran-II sanctions came only in 1998.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-137","question":"The cryogenic engines CE-7.5 and CE-20 power the upper stages of, respectively:","options":["LVM3 and GSLV Mk II","PSLV and GSLV Mk II","GSLV Mk II and LVM3","SSLV and LVM3"],"answer":2,"explanation":"The CE-7.5 (about 7.5 tonnes of thrust) drives the GSLV Mk II's upper stage; the more powerful CE-20 drives LVM3's C25 stage. PSLV and SSLV have no cryogenic stage.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-138","question":"LVM3 uses two S200 solid boosters, a liquid core stage and a cryogenic upper stage. Its liquid core stage is called:","options":["L40","PS2","S139","L110"],"answer":3,"explanation":"The L110 stage carries about 110 tonnes of propellant and is powered by two Vikas engines. L40 strap-ons belong to the GSLV Mk II and S139/PS2 to the PSLV.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-139","question":"The first, suborbital experimental flight of LVM3 in December 2014 (LVM3-X) carried:","options":["The GSAT-19 communication satellite","CARE, a crew module re-entry experiment","The Chandrayaan-2 orbiter on a test run","A batch of 36 OneWeb broadband satellites"],"answer":1,"explanation":"LVM3-X tested the vehicle's atmospheric flight and carried the Crew module Atmospheric Re-entry Experiment, recovered from the Bay of Bengal. GSAT-19 (2017) was its first orbital mission.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-140","question":"In 2022–23, LVM3 flew its first commercial missions, launching satellites for:","options":["SpaceX Starlink","Amazon Kuiper","OneWeb","Iridium"],"answer":2,"explanation":"Two LVM3 flights in October 2022 and March 2023, arranged through NewSpace India Limited, placed 72 OneWeb satellites in low Earth orbit.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-141","question":"The Small Satellite Launch Vehicle (SSLV) has three solid stages topped by a liquid-fuelled:","options":["Cryogenic upper kick stage","PS4 fourth stage","Velocity Trimming Module","Crew escape tower"],"answer":2,"explanation":"The Velocity Trimming Module fine-tunes the satellite's velocity before injection. The PS4 is the PSLV's fourth stage.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-142","question":"The Satish Dhawan Space Centre at Sriharikota lies on a barrier island between the Bay of Bengal and:","options":["Chilika Lake","Kolleru Lake","Vembanad Lake","Pulicat Lake"],"answer":3,"explanation":"Sriharikota separates Pulicat Lake, a brackish lagoon on the Andhra Pradesh–Tamil Nadu border, from the sea. Chilika is in Odisha and Vembanad in Kerala.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-143","question":"ISRO's Space Capsule Recovery Experiment (SRE-1), launched on a PSLV in January 2007, was significant because the capsule:","options":["Was brought back from orbit and recovered from the Bay of Bengal","Docked with an Indian satellite already in low Earth orbit","Carried the first living organisms sent into space by India","Landed on the Moon by parachute as a test for Chandrayaan-1"],"answer":0,"explanation":"SRE-1 orbited for about 12 days and was de-orbited to a splashdown in the Bay of Bengal, proving re-entry and recovery technology needed for crewed flight.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-144","question":"ISRO's RLV-TD, flown from Sriharikota in May 2016 (the HEX mission), was a:","options":["Scramjet engine test carried on a modified sounding rocket","Pad abort test of the crew escape system for Gaganyaan","Winged technology demonstrator for a reusable launch vehicle","First-stage recovery test with a landing on a sea barge"],"answer":2,"explanation":"The Hypersonic Flight Experiment flew a scaled winged vehicle to test re-entry and control for a future reusable launcher; the scramjet test followed in August 2016.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-145","question":"The 'Vikas' rocket engine takes its name from:","options":["Vikram Ambalal Sarabhai","Satish Dhawan","Homi Jehangir Bhabha","Udupi Ramachandra Rao"],"answer":0,"explanation":"VIKAS is an acronym of VIKram Ambalal Sarabhai, honouring the founder of India's space programme.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-146","question":"IRS-1A, India's first operational remote-sensing satellite (1988), was launched by:","options":["An ASLV launched from Sriharikota","A Soviet Vostok rocket from Baikonur","A PSLV launched from Sriharikota","An Ariane rocket launched from Kourou"],"answer":1,"explanation":"IRS-1A went up on a Soviet Vostok from Baikonur in March 1988; the first IRS satellite on an Indian rocket was IRS-P2 on a PSLV in 1994.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-147","question":"INSAT-1B, launched in 1983, was carried into space by:","options":["A US Delta rocket from Cape Canaveral","An Ariane rocket from French Guiana","A Soviet Proton rocket from Baikonur","The US Space Shuttle Challenger"],"answer":3,"explanation":"INSAT-1B was deployed from Challenger in August 1983. INSAT-1A had gone up on a Delta rocket in 1982.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-148","question":"EDUSAT (GSAT-3), launched in 2004, was India's first satellite built exclusively for:","options":["Weather forecasting","Military communication","Education","Navigation"],"answer":2,"explanation":"EDUSAT was dedicated to distance education and tele-education, building on the earlier SITE experiment.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-149","question":"MetSat-1, India's first dedicated meteorological satellite (2002), later renamed Kalpana-1, was launched by:","options":["A PSLV, in that rocket's first launch into a geosynchronous transfer orbit","A GSLV, in its first flight with an upper cryogenic stage that was built in India","An Ariane 5, from the Guiana Space Centre in South America","A Soviet-era Vostok rocket, from the Baikonur launch site"],"answer":0,"explanation":"PSLV-C4 placed MetSat-1 in a geosynchronous transfer orbit, the first such PSLV launch; the satellite was renamed after Kalpana Chawla died on Columbia in 2003.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-150","question":"GSAT-7, launched in 2013 and nicknamed 'Rukmini', is India's first dedicated military communication satellite. It serves the:","options":["Indian Air Force","Indian Army","Indian Navy","Indian Coast Guard"],"answer":2,"explanation":"GSAT-7 links the Navy's ships, submarines and aircraft over the Indian Ocean; GSAT-7A (2018) serves mainly the Air Force.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-151","question":"Which of these statements about Chandrayaan-1 are correct? I. It was launched in October 2008 by PSLV-C11. II. Its Moon Impact Probe was deliberately crashed near the lunar south pole. III. NASA's Moon Mineralogy Mapper on board helped detect water and hydroxyl on the lunar surface. IV. It completed its full planned two-year mission life.","options":["I and III only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"I, II and III are correct. Contact was lost in August 2009, after about ten months, well short of the planned two years, though most objectives had been met.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-152","question":"Match the name given by India with the lunar spot it marks. A. Jawahar Point  B. Tiranga Point  C. Shiv Shakti Point; 1. Landing site of Chandrayaan-3's Vikram lander  2. Impact site of Chandrayaan-1's Moon Impact Probe  3. Spot where Chandrayaan-2's Vikram lander crashed","options":["A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2","A-2, B-3, C-1"],"answer":3,"explanation":"Jawahar Point marks the MIP impact of 14 November 2008 (Nehru's birthday); Tiranga Point marks Chandrayaan-2's crash in 2019; Shiv Shakti Point is Chandrayaan-3's landing site of 23 August 2023.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-153","question":"Chandrayaan-2, with its orbiter, Vikram lander and Pragyan rover, was launched in July 2019 by:","options":["GSLV Mk III (now LVM3)","GSLV Mk II with Russian cryogenic stage","PSLV-XL with six strap-ons","PSLV-QL with four strap-ons"],"answer":0,"explanation":"GSLV Mk III-M1 launched Chandrayaan-2 on 22 July 2019; the 3.8-tonne spacecraft was too heavy for the PSLV.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-154","question":"The LIBS instrument on Chandrayaan-3's Pragyan rover made the first in-situ confirmation, near the lunar south pole, of the presence of:","options":["Water ice","Helium-3","Sulphur","Hydrogen"],"answer":2,"explanation":"Laser-Induced Breakdown Spectroscopy confirmed sulphur in August 2023, along with elements such as aluminium, calcium, iron, titanium and oxygen; the search for hydrogen was ongoing.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-155","question":"ChaSTE, an instrument on Chandrayaan-3's Vikram lander, measured:","options":["Moonquakes and other ground vibrations near the landing site","The temperature profile of the lunar topsoil to about 10 cm","Density of the plasma just above the lunar surface","The precise Earth–Moon distance using laser reflections"],"answer":1,"explanation":"Chandra's Surface Thermophysical Experiment pushed a probe into the regolith to record temperature with depth. ILSA recorded vibrations, RAMBHA-LP plasma, and NASA's retroreflector serves laser ranging.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-156","question":"SHAPE, the experimental payload on Chandrayaan-3's propulsion module, was designed to:","options":["Map water ice in permanently shadowed craters at the poles","Record solar X-ray flares from a vantage point in lunar orbit","Relay radio signals between the Vikram lander and Earth","Observe Earth from lunar orbit as a model for habitable exoplanets"],"answer":3,"explanation":"Spectro-polarimetry of HAbitable Planet Earth studied Earth's reflected light to learn how habitable exoplanets might look. The propulsion module was later moved back into Earth orbit in November 2023.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-157","question":"In September 2023, Chandrayaan-3's Vikram lander carried out a 'hop experiment', in which it:","options":["Released Pragyan a second time after the rover had returned to it","Fired its engines, rose about 40 cm and landed 30–40 cm away","Rolled on wheels about 100 m to a new spot nearer the pole","Lifted off fully and returned its propulsion module to Earth orbit"],"answer":1,"explanation":"The hop showed the lander could restart its engines on the Moon, a step towards future sample-return and crewed missions; it later went into sleep mode for the lunar night.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-158","question":"When the Mars Orbiter Mission entered orbit around Mars on 24 September 2014, India became:","options":["The first Asian country to land a probe on the surface of Mars","The second country, after the United States, to orbit Mars","The first country to reach Mars orbit in its first attempt","The first country to put a probe in orbit around Phobos"],"answer":2,"explanation":"India was the first nation to succeed on its maiden Mars attempt and the first in Asia to reach Mars orbit; the US, the USSR and Europe had reached Mars before, and MOM did not land.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-159","question":"Which of these instruments flew on India's Mars Orbiter Mission?","options":["Moon Mineralogy Mapper","Methane Sensor for Mars","Solar Ultraviolet Imaging Telescope","Alpha Particle X-ray Spectrometer"],"answer":1,"explanation":"MOM carried five payloads, including the Methane Sensor for Mars and the Mars Colour Camera. The M3 flew on Chandrayaan-1, SUIT on Aditya-L1 and APXS on the Pragyan rover.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-160","question":"NavIC satellites broadcast navigation signals in the L5 band and in the:","options":["Ku band","C band","S band","X band"],"answer":2,"explanation":"The first-generation IRNSS satellites transmit in L5 and S bands; the second-generation NVS series adds the L1 band used by most phones.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-161","question":"NVS-01, launched by a GSLV in May 2023 as the first of NavIC's second-generation satellites, was notable for carrying:","options":["An optical laser link to the other NavIC satellites","A hydrogen maser clock imported from Russia","An electric propulsion system for orbit raising","An indigenously developed rubidium atomic clock"],"answer":3,"explanation":"NVS-01 flew an atomic clock developed by ISRO's Space Applications Centre, reducing dependence on imported clocks, whose failures had hit earlier IRNSS satellites.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-162","question":"IRNSS-1H, meant to replace a NavIC satellite whose atomic clocks had failed, was lost in August 2017 because:","options":["The PSLV's heat shield did not separate after launch","Its solar panels failed to unfold once it was in orbit","The cryogenic upper stage of its GSLV shut down early","It collided with debris while raising its own orbit"],"answer":0,"explanation":"On PSLV-C39 the payload fairing failed to separate, so the satellite stayed enclosed and could not reach its orbit; the PSLV has no cryogenic stage.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-163","question":"GAGAN, developed jointly by ISRO and the Airports Authority of India, is a:","options":["Regional navigation constellation independent of GPS","Satellite-based augmentation system that improves GPS accuracy","Ground radar network for civil air traffic control","Weather satellite that forecasts conditions on flight routes"],"answer":1,"explanation":"GPS Aided GEO Augmented Navigation sends corrections through geostationary satellites so aircraft can use GPS for precise approaches. The independent regional constellation is NavIC.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-164","question":"In Mission Shakti (27 March 2019), India destroyed one of its own satellites with a missile. Which of these statements are correct? I. The interceptor was a ballistic missile defence interceptor (PDV Mk-II). II. The target, Microsat-R, was in low Earth orbit at about 300 km. III. The low altitude was chosen partly so that debris would decay quickly. IV. India became the third country to carry out such a test.","options":["I and II only","II, III and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"I, II and III are correct. India was the fourth country, after the United States, Russia and China, to demonstrate a direct-ascent anti-satellite capability.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-165","question":"Rakesh Sharma, the first Indian in space, flew in April 1984 aboard:","options":["Soyuz T-11, visiting the Salyut 7 space station","The US Space Shuttle Challenger on mission STS-41","Soyuz TM-2, visiting the Mir space station","Vostok 6, on a solo orbital flight"],"answer":0,"explanation":"Sharma flew on Soyuz T-11 under the Interkosmos programme and spent about eight days on Salyut 7; Mir was launched only in 1986.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-166","question":"The South Asia Satellite (GSAT-9), launched by India in 2017 for its neighbours, did NOT include which SAARC country, which chose to stay out?","options":["Afghanistan","Sri Lanka","Bangladesh","Pakistan"],"answer":3,"explanation":"Pakistan opted out, so the satellite serves the other SAARC members; it was launched on a GSLV in May 2017.","difficulty":"moderate","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-167","question":"Megha-Tropiques (2011), for studying the tropical water cycle, and SARAL (2013), for ocean altimetry, were joint missions of ISRO with:","options":["JAXA of Japan","CNES of France","NASA of the United States","Roscosmos of Russia"],"answer":1,"explanation":"Both were Indo-French missions with CNES; SARAL carries the French AltiKa altimeter. ISRO's major joint mission with NASA is NISAR.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-168","question":"RISAT-2, India's first radar imaging satellite to reach orbit (2009), was built with the help of:","options":["France","Russia","Israel","The United States"],"answer":2,"explanation":"RISAT-2 used an X-band radar from Israel Aerospace Industries and was rushed into service after 2008; the indigenous RISAT-1 followed in 2012.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-169","question":"HySIS, launched by ISRO in 2018, is an Earth-observation satellite built to use:","options":["Synthetic aperture radar","Laser altimetry","Hyperspectral imaging","Gravity field mapping"],"answer":2,"explanation":"The Hyperspectral Imaging Satellite records the Earth in many narrow, contiguous wavelength bands, useful for farming, forestry, minerals and coastal studies.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-170","question":"EMISAT, launched on PSLV-C45 in April 2019, was built mainly to:","options":["Gather electronic intelligence by picking up radar signals for DRDO","Relay secure communications among Indian Navy ships at sea","Map soil moisture across India's farmland using microwaves","Monitor ocean colour and chlorophyll levels for the fishing industry"],"answer":0,"explanation":"EMISAT carries DRDO's Kautilya electronic-intelligence package to locate enemy radars; naval communication is GSAT-7's role.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-171","question":"GSAT-11, India's heaviest satellite when launched in December 2018 (about 5,850 kg), was put in orbit by:","options":["An Ariane 5 from French Guiana","An LVM3 from Sriharikota","A GSLV Mk II from Sriharikota","A Falcon 9 from Florida"],"answer":0,"explanation":"At that time GSAT-11 was too heavy for LVM3's capacity to geosynchronous transfer orbit (about 4 tonnes), so it went on an Ariane 5.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-172","question":"The Indian Deep Space Network, which tracked Chandrayaan-1 and the Mars Orbiter Mission, is located at:","options":["Hassan, Karnataka","Sriharikota, Andhra Pradesh","Byalalu, near Bengaluru","Thumba, Kerala"],"answer":2,"explanation":"IDSN's large antennas are at Byalalu near Bengaluru, run by ISTRAC. Hassan hosts the Master Control Facility for geostationary satellites.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-173","question":"The Sun–Earth L1 point was chosen for Aditya-L1 mainly because a spacecraft there:","options":["Lies inside Earth's magnetic field, which shields it from radiation","Sits about 384,000 km away, at the same distance as the Moon","Feels no gravity at all, so it never needs fuel to stay there","Can watch the Sun continuously without being eclipsed"],"answer":3,"explanation":"L1, about 1.5 million km sunward of Earth, gives an uninterrupted view of the Sun; it lies outside the magnetosphere and the craft still needs small station-keeping burns in its halo orbit.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-174","question":"Assertion (A): Chandrayaan-3's Vikram lander and Pragyan rover were designed to work for about one lunar day. Reason (R): A lunar day lasts about 14 Earth days, and their systems were not built to survive the extreme cold of the lunar night.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Being solar-powered without heaters for the night, which falls below about −120°C, the two were planned for one lunar daylight period, and they did not wake after the first night.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-175","question":"Dr A. P. J. Abdul Kalam Island, from where long-range Agni missiles are test-fired, was earlier known as:","options":["Rameswaram Island, Tamil Nadu","Wheeler Island, Odisha","Sriharikota Island, Andhra Pradesh","Havelock Island, Andaman and Nicobar"],"answer":1,"explanation":"Wheeler Island off the Odisha coast was renamed in 2015; Chandipur on the mainland houses the Integrated Test Range. Havelock is now Swaraj Dweep.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-176","question":"Arrange these missiles in increasing order of their approximate range: 1. Agni-III  2. Agni-I  3. Agni-V  4. Agni-II","options":["2-4-1-3","2-1-4-3","4-2-1-3","2-4-3-1"],"answer":0,"explanation":"Agni-I is about 700 km, Agni-II about 2,000 km, Agni-III about 3,000 km and Agni-V over 5,000 km.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-177","question":"Agni-V, India's longest-range ballistic missile, was first flight-tested in:","options":["2008","2016","2018","2012"],"answer":3,"explanation":"Agni-V's first test from Wheeler Island was on 19 April 2012; its MIRV version was tested under Mission Divyastra in 2024.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-178","question":"The name of the BrahMos missile is formed from:","options":["The god Brahma and the city of Moscow","The Brahmastra weapon and the Moskit missile","The Brahmaputra and Moskva rivers","The Brahmaputra and the Moscow Aviation Institute"],"answer":2,"explanation":"BrahMos joins the names of India's Brahmaputra and Russia's Moskva rivers, reflecting the Indo-Russian joint venture.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-179","question":"BrahMos is a two-stage missile with a solid-propellant booster followed by a:","options":["Scramjet that sustains hypersonic cruise","Liquid-fuelled ramjet that sustains supersonic cruise","Small turbofan that sustains subsonic cruise","Solid-fuel ducted ramjet that sustains hypersonic cruise"],"answer":1,"explanation":"After the booster burns out, a liquid-fuel ramjet drives BrahMos at about Mach 2.8. Nirbhay uses a turbofan, and the solid-fuel ducted ramjet is a separate DRDO technology for air-to-air missiles.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-180","question":"The first export order for the BrahMos missile, signed in January 2022, came from:","options":["Vietnam","Indonesia","The Philippines","The United Arab Emirates"],"answer":2,"explanation":"The Philippines signed for shore-based anti-ship BrahMos batteries in January 2022; the first deliveries reached it in 2024.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-181","question":"India's Ballistic Missile Defence programme has two layers. Which pairing is correct?","options":["Prithvi Air Defence for interception inside the atmosphere; Advanced Air Defence outside it","Prithvi Air Defence for interception outside the atmosphere; Advanced Air Defence inside it","Akash for interception outside the atmosphere; Prithvi Air Defence inside it","Advanced Air Defence for both layers; Prithvi Air Defence only for cruise missiles"],"answer":1,"explanation":"PAD (Pradyumna) engages missiles at high, exo-atmospheric altitudes, while AAD (Ashwin) intercepts at lower, endo-atmospheric altitudes; Akash is an air-defence SAM, not part of the BMD layers.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-182","question":"India declared its nuclear triad operational in November 2018 when:","options":["Agni-V was handed over to the Strategic Forces Command","Rafale jets were certified to carry nuclear weapons","The K-4 missile was first fired from a submarine","INS Arihant completed its first deterrence patrol"],"answer":3,"explanation":"Arihant's first deterrence patrol added an operational sea-based leg to India's land- and air-based nuclear delivery systems. Rafales arrived only in 2020.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-183","question":"The 'K' in India's K-series submarine-launched ballistic missiles, such as K-15 Sagarika and K-4, stands for:","options":["K. Kasturirangan","Kalpana Chawla","K. Sivan","A. P. J. Abdul Kalam"],"answer":3,"explanation":"The series is named in honour of Dr Kalam, who led India's missile programme.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-184","question":"Match the DRDO system with its description. A. Rudram  B. Helina  C. SMART  D. Shaurya; 1. Missile-assisted release of a lightweight anti-submarine torpedo  2. Helicopter-launched anti-tank guided missile  3. Air-launched anti-radiation missile  4. Canister-launched hypersonic surface-to-surface missile","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"Rudram homes on enemy radar emissions; Helina is the helicopter version of Nag; SMART carries a torpedo far beyond its own range; Shaurya is a land variant related to the K-15.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-185","question":"The Hypersonic Technology Demonstrator Vehicle (HSTDV), flight-tested by DRDO in September 2020, was powered in its cruise phase by a:","options":["Turbojet engine","Liquid-fuel rocket engine","Ramjet engine","Scramjet engine"],"answer":3,"explanation":"HSTDV used an air-breathing scramjet after an Agni-I booster took it to hypersonic speed; a ramjet works only up to about Mach 3–4.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-186","question":"The Medium-Range Surface-to-Air Missile (MRSAM), also known as Barak-8, was developed by DRDO jointly with:","options":["Russia","Israel","France","The United States"],"answer":1,"explanation":"MRSAM was co-developed by DRDO and Israel Aerospace Industries and serves the Navy, Air Force and Army.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-187","question":"The Tejas Mk1 light combat aircraft is powered by:","options":["The indigenous Kaveri turbofan from GTRE","The American General Electric F404 turbofan","The Russian Saturn AL-31FP turbofan","The French Safran M88 turbofan"],"answer":1,"explanation":"The Kaveri engine, meant for Tejas, fell short of requirements, so Tejas flies on the GE F404. The AL-31FP powers the Su-30MKI and the M88 the Rafale.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-188","question":"The Light Combat Aircraft, first flown in January 2001, was named 'Tejas' in 2003 by:","options":["A. P. J. Abdul Kalam","Atal Bihari Vajpayee","Manmohan Singh","George Fernandes"],"answer":1,"explanation":"Prime Minister Atal Bihari Vajpayee named the aircraft Tejas, Sanskrit for radiance, in May 2003.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-189","question":"Match the DRDO laboratory with its location and field. A. DRDL  B. GTRE  C. CVRDE  D. NSTL; 1. Hyderabad, missiles  2. Avadi, combat vehicles  3. Visakhapatnam, underwater weapons  4. Bengaluru, gas turbine engines","options":["A-1, B-2, C-4, D-3","A-3, B-4, C-2, D-1","A-1, B-4, C-2, D-3","A-1, B-4, C-3, D-2"],"answer":2,"explanation":"The Defence Research and Development Laboratory (Hyderabad) leads missile work; GTRE (Bengaluru) built the Kaveri engine; CVRDE (Avadi) developed Arjun; NSTL (Visakhapatnam) develops torpedoes.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-190","question":"DRDO's Defence Research and Development Establishment (DRDE) at Gwalior specialises in:","options":["Protection against chemical and biological agents","High-altitude food and agriculture for troops","Armour plates and explosives for tanks","Sonar and underwater surveillance systems"],"answer":0,"explanation":"DRDE Gwalior develops detection, protection and decontamination for chemical and biological threats. High-altitude agriculture is DIHAR's work at Leh, and sonar NPOL's at Kochi.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-191","question":"Match the Indian Navy shipbuilding project with its class. A. Project 15B  B. Project 17A  C. Project 75  D. Project 28; 1. Nilgiri-class stealth frigates  2. Visakhapatnam-class destroyers  3. Kamorta-class anti-submarine corvettes  4. Kalvari-class submarines","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"Project 15B produced the Visakhapatnam-class destroyers, 17A the Nilgiri-class frigates, 75 the Scorpène-based Kalvari submarines and 28 the Kamorta-class ASW corvettes.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-192","question":"INS Vikrant, India's first indigenously built aircraft carrier, commissioned in 2022, was built by:","options":["Mazagon Dock Shipbuilders, Mumbai","Garden Reach Shipbuilders, Kolkata","Cochin Shipyard Limited, Kochi","Hindustan Shipyard Limited, Visakhapatnam"],"answer":2,"explanation":"Cochin Shipyard built Vikrant to a design by the Navy's Warship Design Bureau; Mazagon Dock builds the Navy's destroyers and Kalvari submarines.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-193","question":"The Su-30MKI fighters of the Indian Air Force are licence-built by Hindustan Aeronautics Limited at:","options":["Bengaluru","Koraput","Kanpur","Nashik"],"answer":3,"explanation":"HAL's Nashik division assembles the Su-30MKI; its Koraput division makes the AL-31FP engines and Bengaluru builds Tejas.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-194","question":"K9 Vajra-T, a 155 mm self-propelled howitzer made by Larsen & Toubro for the Indian Army, is based on a design from:","options":["Sweden","The United States","France","South Korea"],"answer":3,"explanation":"It is adapted from Hanwha's K9 Thunder of South Korea. Sweden's Bofors supplied the FH-77B towed gun of the 1980s.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-195","question":"TAPAS (earlier called Rustom-II), developed by DRDO's Aeronautical Development Establishment, is a:","options":["Medium-altitude long-endurance unmanned aerial vehicle","Airborne early warning and control aircraft","Light utility helicopter for high-altitude posts","Intermediate jet trainer aircraft for pilots"],"answer":0,"explanation":"TAPAS-BH-201 is a MALE drone for surveillance; Netra is the airborne early warning system and the HJT-36 Sitara an intermediate jet trainer.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-196","question":"National Technology Day is observed in India on 11 May to mark:","options":["The Smiling Buddha nuclear test at Pokhran in 1974","The first of the Pokhran-II nuclear tests in 1998","The first launch of an Indian rocket into orbit","The founding of the DRDO by merging defence labs"],"answer":1,"explanation":"The first three Pokhran-II tests took place on 11 May 1998, the day the Hansa-3 aircraft and the Trishul missile were also tested. Smiling Buddha was on 18 May 1974.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-197","question":"Assertion (A): After the Pokhran-II tests of 1998, India declared a voluntary moratorium on further nuclear explosive testing. Reason (R): India signed the Comprehensive Nuclear-Test-Ban Treaty in September 1998.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"India announced a unilateral moratorium in 1998 but has never signed the CTBT, which it views as discriminatory.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-198","question":"Under India's Nuclear Command Authority (2003), the Political Council, the only body that can authorise the use of nuclear weapons, is chaired by the:","options":["President of India","Defence Minister","National Security Adviser","Prime Minister"],"answer":3,"explanation":"The Political Council is chaired by the Prime Minister; the Executive Council, which advises it and carries out its directives, is chaired by the National Security Adviser.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-199","question":"The Defence Research and Development Organisation (DRDO) was formed in:","options":["1958","1948","1962","1969"],"answer":0,"explanation":"DRDO was set up in 1958 by merging the Army's Technical Development Establishments with the Defence Science Organisation.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-200","question":"KAMINI, the small research reactor at Kalpakkam, is notable as the only operating reactor in the world that:","options":["Uses thorium–plutonium fuel and is cooled by liquid lead","Runs on natural uranium moderated by ordinary water","Uses uranium-233 as its fuel","Breeds tritium for fusion research"],"answer":2,"explanation":"KAMINI (Kalpakkam Mini reactor, 1996) uses U-233 bred from thorium, a step towards the third stage of India's nuclear programme.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-201","question":"The Fast Breeder Test Reactor at Kalpakkam, which went critical in 1985, is known for using a fuel first developed in India:","options":["Plutonium–uranium mixed oxide","Plutonium–uranium mixed carbide","Metallic thorium rods","Enriched uranium dioxide"],"answer":1,"explanation":"FBTR runs on a plutonium-rich mixed carbide fuel; the larger Prototype Fast Breeder Reactor uses mixed oxide (MOX) fuel.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-202","question":"CIRUS, the research reactor at Trombay whose plutonium was used for the 1974 nuclear test, was built with help from:","options":["The Soviet Union","France","Canada","The United Kingdom"],"answer":2,"explanation":"CIRUS (Canada-India Reactor, US) was supplied by Canada, with heavy water from the United States; it went critical in 1960.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-203","question":"Match the nuclear power station with its reactor type. A. Tarapur (units 1 and 2)  B. Rawatbhata (RAPS-1)  C. Kudankulam  D. Prototype Fast Breeder Reactor, Kalpakkam; 1. Russian VVER pressurised water reactor  2. US-supplied boiling water reactor  3. Sodium-cooled fast breeder reactor  4. Canadian CANDU-type heavy water reactor","options":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"Tarapur's first two units (1969) are General Electric BWRs, RAPS-1 is a CANDU-type PHWR built with Canada, Kudankulam uses Russian VVERs, and the PFBR is sodium-cooled.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-204","question":"India's first indigenously designed 700 MWe pressurised heavy water reactor to reach criticality, in 2020, is located at:","options":["Kakrapar, Gujarat","Rawatbhata, Rajasthan","Kaiga, Karnataka","Gorakhpur, Haryana"],"answer":0,"explanation":"Kakrapar unit 3 (KAPP-3) went critical in July 2020, the first of the 700 MWe PHWR fleet; earlier indigenous PHWRs were 220 MWe or 540 MWe.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-205","question":"Arrange in chronological order: 1. Department of Atomic Energy set up  2. Atomic Energy Commission set up  3. Tata Institute of Fundamental Research founded  4. APSARA reactor goes critical","options":["2-3-1-4","3-2-4-1","3-2-1-4","3-1-2-4"],"answer":2,"explanation":"TIFR (1945), Atomic Energy Commission (1948), DAE (1954) and APSARA, Asia's first research reactor (1956).","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-206","question":"The Tata Institute of Fundamental Research was founded in 1945, with the support of the Sir Dorabji Tata Trust, by:","options":["C. V. Raman","Vikram Sarabhai","Meghnad Saha","Homi J. Bhabha"],"answer":3,"explanation":"Homi Bhabha founded TIFR in Bombay; it became the cradle of India's atomic energy programme. Sarabhai founded the Physical Research Laboratory (1947).","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-207","question":"India's first uranium mine, worked by the Uranium Corporation of India since 1967, is at:","options":["Tummalapalle, Andhra Pradesh","Domiasiat, Meghalaya","Jaduguda, Jharkhand","Rawatbhata, Rajasthan"],"answer":2,"explanation":"Jaduguda in East Singhbhum was India's first uranium mine. Tummalapalle is a newer, large low-grade deposit and Domiasiat an unmined deposit in Meghalaya.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-208","question":"DNA fingerprinting in India was pioneered in the late 1980s by Lalji Singh at the:","options":["National Chemical Laboratory, Pune","Centre for Cellular and Molecular Biology, Hyderabad","National Institute of Immunology, New Delhi","Indian Institute of Science, Bengaluru"],"answer":1,"explanation":"Lalji Singh developed the technique at CCMB Hyderabad and later founded the Centre for DNA Fingerprinting and Diagnostics there; it was first used in an Indian paternity case in 1988.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-209","question":"Cervavac, approved in 2022 and developed by the Serum Institute of India with the Department of Biotechnology, is India's first indigenous vaccine against:","options":["Rotavirus","Human papillomavirus","Dengue virus","Japanese encephalitis"],"answer":1,"explanation":"Cervavac is a quadrivalent HPV vaccine to prevent cervical cancer. Rotavac, the indigenous rotavirus vaccine, came earlier from Bharat Biotech.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-210","question":"Match the COVID-19 vaccine used in India with its platform. A. Covaxin  B. Covishield  C. Corbevax  D. ZyCoV-D; 1. Protein subunit  2. Plasmid DNA  3. Inactivated whole virus  4. Chimpanzee adenovirus vector","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Covaxin (Bharat Biotech) is an inactivated vaccine; Covishield is the ChAdOx1 vector vaccine; Corbevax (Biological E) is a protein subunit vaccine; ZyCoV-D (Zydus) was the world's first DNA vaccine approved for humans.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-211","question":"DMH-11, the genetically modified mustard hybrid cleared for environmental release by GEAC in 2022, uses the barnase–barstar gene system in order to:","options":["Make the plant resistant to sap-sucking pests such as aphids","Raise oil content and lower erucic acid in the seed","Create male sterility and then restore fertility for hybrid seed","Let the crop survive drought and salty soils in dry regions"],"answer":2,"explanation":"Barnase makes one parent line male-sterile and barstar restores fertility in the hybrid, allowing large-scale hybrid seed production; the genes come from the bacterium Bacillus amyloliquefaciens.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-212","question":"India set up a separate Department of Biotechnology, under the Ministry of Science and Technology, in:","options":["1972","1991","2001","1986"],"answer":3,"explanation":"The DBT was created in 1986 out of the National Biotechnology Board formed in 1982.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-213","question":"The Genome India Project, launched by the Department of Biotechnology in 2020, aims to:","options":["Sequence the genomes of about 10,000 Indians to map the country's genetic variation","Create genetically modified versions of major Indian food crops for drought tolerance","Sequence the genome of every new-born child in India to screen for inherited disease","Build a national DNA database of convicted criminals for use by the police forces"],"answer":0,"explanation":"The project sequenced whole genomes of about 10,000 people from many communities to build a reference database for research and medicine.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-214","question":"The polymerase chain reaction (PCR), the basis of RT-PCR tests, is a technique to:","options":["Separate DNA fragments by size in a gel","Make millions of copies of a chosen DNA segment","Cut DNA at specific recognition sequences","Join DNA fragments into a bacterial plasmid"],"answer":1,"explanation":"PCR, devised by Kary Mullis in 1983, amplifies a target DNA sequence through repeated heating and cooling cycles. Gel electrophoresis separates fragments; restriction enzymes cut and ligase joins DNA.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-215","question":"Assertion (A): RT-PCR tests can detect RNA viruses such as SARS-CoV-2. Reason (R): The enzyme reverse transcriptase first converts the viral RNA into DNA, which PCR then amplifies.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"PCR copies only DNA, so the RNA genome must first be reverse-transcribed into complementary DNA; that is why the test is called reverse transcription PCR.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-216","question":"The 2020 Nobel Prize in Chemistry for developing the CRISPR-Cas9 genome-editing method was awarded to:","options":["Jennifer Doudna and Feng Zhang","Emmanuelle Charpentier and Jennifer Doudna","Emmanuelle Charpentier and George Church","Feng Zhang and George Church"],"answer":1,"explanation":"Charpentier and Doudna shared the prize, the first science Nobel won by two women alone; Zhang and Church also did major CRISPR work but were not awarded.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-217","question":"Which of these statements about Nobel Prizes in science linked to India are correct? I. C. V. Raman won the 1930 Physics prize for his work on the scattering of light. II. Har Gobind Khorana shared the 1968 Medicine prize for work on interpreting the genetic code. III. S. Chandrasekhar shared the 1983 Physics prize for work on the structure and evolution of stars. IV. Venkatraman Ramakrishnan shared the 2009 Chemistry prize for studies of the ribosome.","options":["I and III only","I, II and III only","I, III and IV only","I, II, III and IV"],"answer":3,"explanation":"All four are correct; Raman remains the only one who did his prize-winning work in India.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-218","question":"National Science Day is celebrated on 28 February because on that day in 1928:","options":["C. V. Raman announced the discovery of the Raman effect","Jagadish Chandra Bose demonstrated the crescograph","The Indian Institute of Science was opened in Bangalore","Satyendra Nath Bose sent his paper on photon statistics to Einstein"],"answer":0,"explanation":"Raman announced the effect on 28 February 1928; it won him the 1930 Physics Nobel. IISc was founded in 1909.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-219","question":"Particles called 'bosons' are named after:","options":["Jagadish Chandra Bose","Ananda Mohan Bose","Debendra Mohan Bose","Satyendra Nath Bose"],"answer":3,"explanation":"S. N. Bose's 1924 work on photon statistics, extended by Einstein, gave Bose–Einstein statistics; particles obeying it, such as photons and the Higgs, are bosons.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-220","question":"The thermal ionisation equation, which helped explain the spectra and temperatures of stars, was given in 1920 by:","options":["Meghnad Saha","S. Chandrasekhar","C. V. Raman","Satyendra Nath Bose"],"answer":0,"explanation":"The Saha ionisation equation links a gas's ionisation to its temperature and pressure, letting astronomers classify stars by temperature.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-221","question":"The Chandrasekhar limit is the maximum mass of a stable:","options":["Neutron star, about 1.4 times the Sun's mass","White dwarf, about 3 times the Sun's mass","White dwarf, about 1.4 times the Sun's mass","Black hole, about 1.4 times the Sun's mass"],"answer":2,"explanation":"Above about 1.4 solar masses electron degeneracy pressure cannot support a white dwarf, so it collapses further. Black holes have no upper mass limit of this kind.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-222","question":"Match the astronomical facility with its location. A. Giant Metrewave Radio Telescope  B. 3.6 m Devasthal Optical Telescope  C. Indian Astronomical Observatory  D. Mount Abu Infrared Observatory; 1. Hanle, Ladakh  2. Narayangaon, near Pune  3. Rajasthan, run by PRL  4. Nainital district, run by ARIES","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"answer":0,"explanation":"GMRT is near Narayangaon (Pune district), Devasthal near Nainital (ARIES), the Indian Astronomical Observatory at Hanle (IIA) and the Mount Abu observatory is run by the Physical Research Laboratory.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-223","question":"LIGO-India, the gravitational-wave observatory approved by the Union Cabinet in 2023, is to be built in:","options":["Theni district, Tamil Nadu","Hanle, Ladakh","Chitradurga district, Karnataka","Hingoli district, Maharashtra"],"answer":3,"explanation":"The site is in Hingoli district, Maharashtra. Theni is the proposed site of the India-based Neutrino Observatory and Hanle hosts optical telescopes.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-224","question":"India is a full member of ITER, the international experimental fusion reactor being built at:","options":["Geneva, Switzerland","Cadarache, France","Garching, Germany","Culham, United Kingdom"],"answer":1,"explanation":"ITER, a tokamak meant to show fusion's feasibility, is at Cadarache in southern France; India joined in 2005. Geneva hosts CERN, the particle physics laboratory.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-225","question":"Arrange India's Antarctic research bases in the order they were set up: 1. Maitri  2. Bharati  3. Dakshin Gangotri","options":["1-3-2","3-2-1","3-1-2","1-2-3"],"answer":2,"explanation":"Dakshin Gangotri (1983–84) was buried by ice and decommissioned; Maitri followed in 1989 and Bharati in 2012.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-science-tech-226","question":"In the seven-layer OSI model, at which layers do TCP and IP respectively operate?","options":["Network layer and data link layer","Transport layer and network layer","Session layer and transport layer","Transport layer and data link layer"],"answer":1,"explanation":"TCP provides reliable end-to-end delivery at the transport layer (layer 4); IP handles addressing and routing at the network layer (layer 3).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-227","question":"By default, secure web traffic using HTTPS runs over TCP port:","options":["80","8080","25","443"],"answer":3,"explanation":"HTTPS uses port 443; plain HTTP uses 80, FTP control uses 21 and SMTP mail uses 25.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-228","question":"An IPv4 address is 32 bits long. Roughly how many distinct addresses can the IPv4 scheme provide?","options":["About 65 thousand (2^16)","About 4.3 million (2^22)","About 4.3 billion (2^32)","About 18 quintillion (2^64)"],"answer":2,"explanation":"2^32 = 4,294,967,296, about 4.3 billion, too few for today's devices, which is why 128-bit IPv6 was introduced.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-229","question":"Unlike a computer virus, a computer worm:","options":["Disguises itself as useful software to trick the user into installing it","Encrypts the victim's files and then demands a ransom to unlock them","Spreads across networks on its own without attaching to a host file","Can spread only through removable media such as USB flash drives"],"answer":2,"explanation":"A worm self-replicates over networks without needing a host program or user action; a virus attaches to files. Disguise describes a Trojan and file encryption describes ransomware.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-230","question":"An attacker types database commands into a website's login box so that the site's database reveals or changes data. This attack is called:","options":["Cross-site scripting","SQL injection","Session hijacking","Phishing"],"answer":1,"explanation":"SQL injection exploits input that is passed unchecked into database queries. Cross-site scripting injects scripts that run in other users' browsers.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-231","question":"A distributed denial-of-service (DDoS) attack mainly aims to:","options":["Make a service unavailable by flooding it with traffic from many sources","Steal users' passwords by sending them convincing fake login pages by e-mail","Secretly record keystrokes on infected computers across a network","Change the content of a website to display the attacker's message"],"answer":0,"explanation":"DDoS uses many machines, often a botnet, to overwhelm a server or network so genuine users cannot reach it. Fake login pages are phishing and altering a site is defacement.","difficulty":"moderate","source":"SSC CGL · IBPS SO"},
  {"id":"gk-science-tech-232","question":"In public-key (asymmetric) encryption, if A wants to send B a message that only B can read, A should encrypt it with:","options":["A's own private key","A's own public key","B's private key","B's public key"],"answer":3,"explanation":"Anything encrypted with B's public key can be decrypted only with B's private key, which only B holds. A's private key is used for signing, not secrecy, and A never has B's private key.","difficulty":"very-hard","source":"UPSC Prelims · IBPS SO"},
  {"id":"gk-science-tech-233","question":"Assertion (A): A digital signature lets the receiver check who sent a message and that it was not altered. Reason (R): The sender signs with their private key, and anyone can verify the signature with the matching public key.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Only the holder of the private key can produce a signature that the public key verifies, and any change to the message breaks verification, giving authenticity and integrity.","difficulty":"hard","source":"UPSC Prelims · IBPS SO"},
  {"id":"gk-science-tech-234","question":"In Shreya Singhal v. Union of India (2015), the Supreme Court struck down which provision of the Information Technology Act, 2000 as unconstitutional?","options":["Section 69A, on blocking public access to websites","Section 79, on safe harbour for intermediaries","Section 43, on penalties for damage to computers","Section 66A, on sending offensive messages online"],"answer":3,"explanation":"Section 66A was struck down for vagueness, violating free speech. The Court upheld Section 69A blocking powers and read down Section 79.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-235","question":"Under the Digital Personal Data Protection Act, 2023, complaints of personal data breaches are handled, and penalties imposed, by the:","options":["Data Protection Authority of India","Data Protection Board of India","Indian Computer Emergency Response Team","Telecom Regulatory Authority of India"],"answer":1,"explanation":"The 2023 Act creates the Data Protection Board of India. A 'Data Protection Authority' was proposed in the withdrawn 2019 Bill; CERT-In handles cyber incidents.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-236","question":"The Open Network for Digital Commerce (ONDC), launched in 2022, is:","options":["A government-run online marketplace used by ministries for public procurement","A payment system that settles card payments for small shops","An open network that lets different e-commerce apps trade with each other","A fibre broadband network to connect every gram panchayat"],"answer":2,"explanation":"ONDC lets a buyer on one app buy from a seller listed on another, built on open protocols like UPI. Public procurement is GeM's role and village broadband is BharatNet.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-science-tech-237","question":"The National Supercomputing Mission, launched in 2015, is implemented by C-DAC together with:","options":["IIT Bombay","ISRO, Bengaluru","IISc Bengaluru","DRDO, New Delhi"],"answer":2,"explanation":"C-DAC, Pune, and the Indian Institute of Science, Bengaluru, implement the mission for the Ministry of Electronics and IT and the Department of Science and Technology.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-238","question":"Pratyush, a high-performance computing system installed in 2018 at the Indian Institute of Tropical Meteorology, Pune, is used mainly for:","options":["Weather and climate forecasting","Simulation of nuclear reactor cores","Analysis of genome sequences","Cryptanalysis for defence agencies"],"answer":0,"explanation":"Pratyush (IITM Pune) and Mihir (NCMRWF, Noida) run India's weather and climate models under the Ministry of Earth Sciences.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-239","question":"Moore's law, as revised by Gordon Moore in 1975, states that:","options":["Processor clock speeds double roughly every twelve months","The cost of an equivalent computer halves about every ten years","Storage capacity on a disk grows in a straight line with time","Transistor counts on a chip double about every two years"],"answer":3,"explanation":"Moore observed that transistor counts on integrated circuits double roughly every two years; clock speeds stopped scaling like this in the mid-2000s.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-240","question":"In 2023 the Union Cabinet approved Micron Technology's semiconductor assembly, testing, marking and packaging (ATMP) plant at:","options":["Dholera, Gujarat","Hosur, Tamil Nadu","Noida, Uttar Pradesh","Sanand, Gujarat"],"answer":3,"explanation":"Micron's ATMP unit is at Sanand. Dholera was later chosen for the Tata–PSMC chip fabrication plant approved in 2024.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-241","question":"Wi-Fi wireless local area networks are based on which family of IEEE standards?","options":["IEEE 802.3","IEEE 802.15","IEEE 802.16","IEEE 802.11"],"answer":3,"explanation":"Wi-Fi follows IEEE 802.11. Wired Ethernet is 802.3, 802.15 covers personal area networks such as Bluetooth and 802.16 is WiMAX.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-242","question":"A kibibyte (KiB) is exactly:","options":["1,000 bytes","1,024 bytes","1,000 bits","1,024 bits"],"answer":1,"explanation":"Binary prefixes use powers of 2: 1 KiB = 2^10 = 1,024 bytes, while the SI kilobyte (kB) is 1,000 bytes.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-243","question":"In machine learning, 'supervised learning' means training a model on:","options":["Unlabelled data, so that it finds hidden groupings by itself","Rewards and penalties received from an environment it acts in","Examples labelled with the correct outputs it should predict","Data generated entirely by another trained model"],"answer":2,"explanation":"Supervised learning maps inputs to known labels, as in spam filters trained on marked e-mails. Finding structure in unlabelled data is unsupervised learning; rewards define reinforcement learning.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-244","question":"The 'transformer' architecture used in most large language models was introduced in a 2017 research paper titled:","options":["Attention Is All You Need","Deep Residual Learning for Image Recognition","Generative Adversarial Nets","ImageNet Classification with Deep Convolutional Networks"],"answer":0,"explanation":"Researchers at Google proposed the transformer, built on self-attention, in 'Attention Is All You Need' (2017). The other titles introduced ResNets, GANs and AlexNet.","difficulty":"hard","source":"UPSC Prelims · IBPS SO"},
  {"id":"gk-science-tech-245","question":"The 'Kessler syndrome', a concern in debates on anti-satellite tests and space debris, describes:","options":["Damage to satellite electronics caused by strong solar storms","A cascade of collisions in which debris causes ever more debris","Loss of bone density suffered by astronauts on long space missions","Radio interference between satellites in neighbouring slots"],"answer":1,"explanation":"Donald Kessler warned in 1978 that crowded orbits could reach a point where each collision creates fragments that cause further collisions, making some orbits unusable.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-246","question":"A satellite in a geosynchronous orbit that is inclined to the equator, like some NavIC satellites, appears to an observer on the ground to:","options":["Stay fixed at one single point in the sky all day long","Rise in the west and set in the east every day","Trace a figure-of-eight path in the sky each day","Cross the whole sky several times each day"],"answer":2,"explanation":"Its period matches Earth's rotation, but the inclination makes it drift north and south, tracing an analemma-like figure of eight; only a geostationary satellite over the equator appears fixed.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-science-tech-247","question":"The International Space Station, at about 400 km altitude, orbits Earth roughly 16 times a day, while a geostationary satellite orbits once a day. This is because:","options":["Lower orbits need higher speeds and shorter paths, giving a period of about 90 minutes","The ISS keeps its engines firing all the time, while geostationary satellites coast freely","Geostationary satellites move against the Earth's rotation, which slows them","Atmospheric drag at 400 km pushes the ISS forward and speeds it up each orbit"],"answer":0,"explanation":"By Kepler's third law the period grows with orbital radius; at about 400 km the speed is about 7.7 km/s and the period about 92 minutes. Drag slows the ISS, and it needs only occasional reboosts.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-science-tech-248","question":"Software released under the GNU General Public License (GPL) comes with the condition that:","options":["Distributed modified versions must also be released under the GPL, with source code","It may be used only for non-commercial, academic and educational purposes","Its source code must stay secret, though the compiled program may be shared freely","It must be registered with a government agency before it can legally be distributed"],"answer":0,"explanation":"The GPL is a 'copyleft' licence: anyone may use, study, change and sell the software, but distributed derivatives must carry the same freedoms, including access to source code.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
  {"id":"gk-science-tech-249","question":"The 2019 Nobel Prize in Chemistry, shared by John Goodenough, Stanley Whittingham and Akira Yoshino, was awarded for developing:","options":["Lithium-ion batteries","Organic light-emitting diodes","Graphene","Blue light-emitting diodes"],"answer":0,"explanation":"The three laid the groundwork for rechargeable lithium-ion batteries. Blue LEDs won the 2014 Physics prize and graphene the 2010 Physics prize.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-science-tech-250","question":"In a computer, 'cache memory' is:","options":["Permanent storage that keeps its data when the power is switched off","A part of the hard disk used as extra memory when the RAM is full","A small, fast memory near the processor that holds frequently used data","Memory set aside only for the graphics card to store images shown on screen"],"answer":2,"explanation":"Cache (usually SRAM) sits between the CPU and main memory to cut access time. Using disk space when RAM is full is virtual memory, and permanent storage is non-volatile memory.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS SO"},
];

export default questions;
